INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (100,100,'Vinpearl Resort Nha Trangggghhuhuihuhu','Đảo Hòn Tre, Phường Vĩnh Nguyên, Nha Trang',22330,'Khu nghỉ dưỡng 5 sao sang trọng tọa lạc trên đảo Hòn Tre xinh đẹp với bãi biển riêng tuyệt đẹp, hồ bơi vô cực, spa đẳng cấp thế giới, nhà hàng fine dining và các hoạt động giải trí phong phú. Resort cung cấp trải nghiệm nghỉ dưỡng hoàn hảo với dịch vụ 5 sao và tầm nhìn panorama ra vịnh Nha Trang.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',5);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (102,102,'Marina Bay Vung Tau Resort & Spa','Đường Thi Sách',26509,'Khu nghỉ dưỡng 4 sao tọa lạc tại bãi biển Thắng Tam xinh đẹp với thiết kế hiện đại và tầm nhìn tuyệt vời ra vịnh Vũng Tàu. Resort có hồ bơi ngoài trời, spa thư giãn, nhà hàng hải sản tươi ngon và các phòng nghỉ thoải mái với ban công riêng hướng biển.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (107,107,'Emerald Bay Resort Phu Quoc','Bãi Khem',31081,'Resort 5 sao tọa lạc tại bãi Khem - một trong những bãi biển đẹp nhất Phú Quốc với cát trắng mịn và nước biển trong xanh như ngọc lục bảo. Resort có thiết kế sang trọng hòa quyện với thiên nhiên nhiệt đới.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',5);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (108,108,'Sunset Beach Resort Phu Quoc','Bãi Sao',31081,'Resort 4 sao nằm trên bãi Sao nổi tiếng với hoàng hôn tuyệt đẹp. Thiết kế tropical hiện đại với các bungalow gần biển và dịch vụ lặn ngắm san hô chuyên nghiệp.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (109,109,'Pearl Island Resort Phu Quoc','Bãi Trường',31081,'Resort boutique 4 sao với concept ngọc trai, nằm trên bãi Trường dài 20km. Có spa ngọc trai độc đáo, nhà hàng hải sản tươi sống và tour câu cá đêm.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (200,200,'Amiana Resort and Villas Nha Trang','Đường Phạm Văn Đồng, Phường Vĩnh Hải, Nha Trang',22330,'Khu nghỉ dưỡng 5 sao cao cấp với thiết kế hiện đại, nằm trên bãi biển riêng tuyệt đẹp. Resort có hồ bơi vô cực, spa đẳng cấp quốc tế, nhà hàng fine dining và các villa sang trọng với hồ bơi riêng. Amiana mang đến trải nghiệm nghỉ dưỡng đẳng cấp với dịch vụ chu đáo và không gian yên tĩnh.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',5);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (101,101,'Ana Mandara Cam Ranh','Đường Nguyễn Tất Thành',22330,'Khu nghỉ dưỡng 5 sao sang trọng tọa lạc trên bãi biển Cam Ranh tuyệt đẹp với thiết kế kiến trúc độc đáo kết hợp phong cách Việt Nam truyền thống và hiện đại. Resort có villa riêng biệt với hồ bơi, spa đẳng cấp quốc tế, nhà hàng fine dining và các hoạt động thể thao biển phong phú.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',5);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (110,110,'Tropical Paradise Resort Phu Quoc','Bãi Ông Lang',31081,'Resort 4 sao eco-friendly với thiết kế thân thiện môi trường. Nằm tại bãi Ông Lang yên tĩnh, có rừng dừa xanh mướt và chương trình bảo tồn rùa biển.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (111,111,'Coconut Bay Resort Phu Quoc','Bãi Dài',31081,'Resort 3 sao gia đình với không gian ấm cúng giữa rừng dừa. Có bãi biển riêng yên tĩnh, phù hợp nghỉ dưỡng thư giãn và các hoạt động gia đình.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',3);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (112,112,'Diamond Bay Resort Nha Trang','Bãi Dài Cam Ranh',22330,'Resort 5 sao sang trọng với concept kim cương, nằm trên bãi Dài Cam Ranh tuyệt đẹp. Có sân golf 18 lỗ, spa kim cương và dịch vụ butler riêng cho từng villa.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',5);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (113,113,'Sunrise Beach Resort Nha Trang','Bãi Dương Cam Lâm',22330,'Resort 4 sao với concept bình minh tuyệt đẹp, nằm trên bãi Dương với view hoàng hôn và bình minh tuyệt vời. Có yoga bãi biển và tour ngắm bình minh chuyên nghiệp.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (114,114,'Ocean Pearl Resort Nha Trang','Bãi Bắc Cam Ranh',22330,'Resort 4 sao với concept ngọc trai đại dương, nằm trên bãi Bắc Cam Ranh. Có trung tâm lặn biển chuyên nghiệp và spa ngọc trai độc đáo với liệu pháp tắm ngọc trai.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (115,115,'Blue Lagoon Resort Nha Trang','Vịnh Ninh Vân',22330,'Resort 4 sao với concept đầm xanh nhiệt đới, nằm trong vịnh Ninh Vân yên tĩnh. Có kayak miễn phí và tour khám phá đầm xanh với hệ sinh thái phong phú.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (116,116,'Coral Bay Resort Nha Trang','Bãi Tràm Vạn Ninh',22330,'Resort 3 sao gia đình với concept san hô nhiệt đới, nằm tại bãi Tràm yên tĩnh. Có tour lặn ngắm san hô và hoạt động gia đình thân thiện với môi trường biển.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',3);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (117,117,'Ancient Town Resort Hoi An','Phố Cổ Hội An',20401,'Resort 5 sao boutique với kiến trúc cổ điển Hội An, nằm ngay trung tâm phố cổ. Có tour đi thuyền sông Thu Bồn, làng nghề truyền thống và ẩm thực đặc sản Hội An.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',5);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (118,118,'Lantern Riverside Resort Hoi An','Bờ sông Thu Bồn',20401,'Resort 4 sao với concept đèn lồng Hội An, nằm bên bờ sông Thu Bồn thơ mộng. Có lễ hội đèn lồng hàng tháng và workshop làm đèn lồng truyền thống.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (121,121,'Golden Bridge Resort Hoi An','Cầu Vàng Hội An',20401,'Resort 3 sao gia đình với concept cầu vàng, có tour tham quan cầu vàng và hoạt động gia đình thân thiện với giá cả phải chăng.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',3);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (103,103,'Fusion Suites Vung Tau','Đường Hoàng Hoa Thám',26512,'Khách sạn 4 sao hiện đại với thiết kế sang trọng tọa lạc tại trung tâm Vũng Tàu. Khách sạn có hồ bơi trên tầng thượng với tầm nhìn toàn cảnh thành phố, spa thư giãn, nhà hàng buffet đa dạng và các suite rộng rãi với ban công riêng. Vị trí thuận lợi gần bãi biển và các điểm tham quan nổi tiếng.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (104,104,'Melia Ho Tram Beach Resort','Đường Ven Biển',26623,'Khu nghỉ dưỡng 5 sao sang trọng tọa lạc trên bãi biển Hồ Tràm tuyệt đẹp với thiết kế kiến trúc Tây Ban Nha độc đáo. Resort có bãi biển riêng dài 1km, 3 hồ bơi ngoài trời, spa YHI đẳng cấp quốc tế, sân golf 18 lỗ và các villa biệt lập với hồ bơi riêng. Trải nghiệm nghỉ dưỡng đẳng cấp châu Âu giữa thiên nhiên nhiệt đới Việt Nam.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',5);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (105,105,'Lang Co Beach Resort','Đường Cảnh Dương',20320,'Khu nghỉ dưỡng 4 sao tọa lạc tại vịnh Lăng Cô tuyệt đẹp với bãi biển cát trắng dài 10km và núi rừng xanh mướt. Resort có thiết kế hài hòa với thiên nhiên, hồ bơi ngoài trời, spa thư giãn, nhà hàng hải sản tươi ngon và các phòng nghỉ thoải mái với tầm nhìn ra biển hoặc núi. Vị trí lý tưởng gần Huế và Đà Nẵng.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (119,119,'Silk Road Resort Hoi An','Làng Lụa Hội An',20401,'Resort 4 sao với concept con đường tơ lụa, nằm tại làng lụa truyền thống Hội An. Có workshop dệt lụa thủ công và bảo tàng tơ lụa Việt Nam.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
INSERT INTO KHU_NGHI_DUONG (ID,ID_DOI_TAC,TEN,DIA_CHI,PHUONG_ID,MO_TA,IMG_360_URL,DANH_GIA) VALUES (120,120,'River Garden Resort Hoi An','Vườn Rau Hội An',20401,'Resort 4 sao eco-friendly với concept vườn rau bên sông, có tour nông trại hữu cơ và lớp học nấu ăn với rau củ tự trồng.','https://vr360.com.vn/projects/winhouse-villa/#node22,62.94,8.32,140,4',4);
