INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (107,120,3,4,'Resort 4 sao eco-friendly với concept vườn rau độc đáo! Garden Family Suite rộng rãi, phù hợp gia đình. Tour nông trại giáo dục. Kids club eco thú vị.',TIMESTAMP'2025-05-14 07:34:24');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (108,120,4,4,'River Garden thực sự là vườn rau bên sông tuyệt vời! Eco Suite Riverside có view sông đẹp. Vườn rau hữu cơ. Lớp học nấu ăn với rau tự trồng thú vị.',TIMESTAMP'2025-05-23 07:34:24');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (109,120,5,4,'Nghỉ dưỡng eco tuyệt vời tại Hội An! River Garden View có view vườn rau đẹp. Tour nông trại hữu cơ giáo dục. Gym hiện đại. Lớp học nấu ăn thú vị.',TIMESTAMP'2025-05-17 07:34:24');
