INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (111,120,7,4,'River Garden Resort có concept vườn rau rất sáng tạo! Garden View Room yên tĩnh. Tour nông trại hữu cơ đáng trải nghiệm. Lớp học nấu ăn thú vị.',TIMESTAMP'2025-05-19 07:34:24');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (112,120,8,4,'Kỳ nghỉ vườn rau đáng nhớ tại Hội An! Garden Family Suite rộng rãi cho gia đình. Vườn rau hữu cơ Hội An tuyệt đẹp. Resort eco 4 sao chất lượng cao.',TIMESTAMP'2025-05-28 07:34:24');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (113,121,1,3,'Golden Bridge Resort Hội An có concept cầu vàng tuyệt đẹp! Tour tham quan cầu vàng thú vị. Hoạt động gia đình thân thiện. Giá cả phải chăng cho resort 3 sao!',TIMESTAMP'2025-05-25 07:34:26');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (114,121,2,3,'Kỳ nghỉ gia đình thú vị tại Hội An! Golden Bridge Villa có view cầu vàng đẹp. Tour tham quan cầu vàng. Spa thư giãn. Giá cả hợp lý cho gia đình!',TIMESTAMP'2025-05-20 07:34:26');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (115,121,3,3,'Resort 3 sao gia đình với concept cầu vàng độc đáo! Golden Family Room rộng rãi, phù hợp gia đình có trẻ em. Hoạt động gia đình thú vị. Kids club vui chơi.',TIMESTAMP'2025-05-13 07:34:26');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (116,121,4,3,'Golden Bridge thực sự là resort cầu vàng tuyệt vời! Golden Suite Deluxe có view cầu đẹp. Tour tham quan cầu vàng thú vị cho cả gia đình.',TIMESTAMP'2025-05-22 07:34:26');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (117,121,5,3,'Nghỉ dưỡng gia đình tuyệt vời tại Hội An! Golden Bridge View có view cầu vàng đẹp. Hoạt động gia đình thân thiện. Gym cơ bản. Giá cả phải chăng.',TIMESTAMP'2025-05-16 07:34:26');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (118,121,6,4,'Resort cầu vàng với thiết kế gia đình ấm cúng! Golden Bridge Villa có view cầu vàng tuyệt vời. Tour tham quan cầu vàng. Spa thư giãn. Dịch vụ đưa đón thuận tiện.',TIMESTAMP'2025-05-24 07:34:26');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (119,121,7,3,'Golden Bridge Resort có concept cầu vàng rất thú vị! Golden Standard Room giá cả phải chăng. Tour tham quan cầu vàng đáng trải nghiệm cho gia đình.',TIMESTAMP'2025-05-18 07:34:26');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (120,121,8,3,'Kỳ nghỉ cầu vàng đáng nhớ tại Hội An! Golden Family Room rộng rãi cho gia đình. Cầu vàng Hội An tuyệt đẹp. Resort 3 sao gia đình chất lượng tốt.',TIMESTAMP'2025-05-27 07:34:26');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (121,103,1,5,'Khách sạn tuyệt vời! Phòng rộng rãi, sạch sẽ và view đẹp. Nhân viên phục vụ rất chu đáo và thân thiện. Vị trí thuận lợi gần trung tâm Vũng Tàu.',TIMESTAMP'2025-05-18 07:34:48');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (122,103,2,4,'Khách sạn đẹp, tiện nghi hiện đại. Hồ bơi trên tầng thượng có view tuyệt vời. Buffet sáng đa dạng và ngon. Chỉ có điều giá hơi cao một chút.',TIMESTAMP'2025-05-25 07:34:48');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (123,103,3,5,'Lần đầu ở Fusion Suites và rất hài lòng. Phòng suite rộng, có ban công đẹp. Spa thư giãn tuyệt vời sau ngày dài tham quan. Sẽ quay lại lần sau!',TIMESTAMP'2025-05-11 07:34:49');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (124,103,4,4,'Khách sạn tốt, vị trí thuận lợi. Phòng sạch sẽ, tiện nghi đầy đủ. Nhân viên lễ tân hỗ trợ nhiệt tình. Gym và hồ bơi khá ok. Giá cả hợp lý.',TIMESTAMP'2025-05-28 07:34:49');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (125,103,5,5,'Trải nghiệm tuyệt vời tại Fusion Suites! Phòng Penthouse sang trọng, view toàn cảnh thành phố. Dịch vụ 5 sao, đặc biệt là nhà hàng có món ăn ngon. Highly recommended!',TIMESTAMP'2025-05-21 07:34:49');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (126,103,6,4,'Khách sạn hiện đại, phòng thoáng mát. Bữa sáng buffet phong phú. Hồ bơi infinity pool đẹp. Vị trí gần biển và trung tâm mua sắm. Chất lượng tốt cho mức giá.',TIMESTAMP'2025-05-15 07:34:49');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (127,103,7,5,'Kỳ nghỉ hoàn hảo! Phòng suite gia đình rộng rãi, phù hợp cho cả gia đình. Con em thích hồ bơi và khu vui chơi. Nhân viên rất chuyên nghiệp và thân thiện.',TIMESTAMP'2025-05-30 07:34:49');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (128,103,8,4,'Fusion Suites là lựa chọn tốt khi đến Vũng Tàu. Phòng đẹp, sạch sẽ. Dịch vụ spa thư giãn. Nhà hàng có món ăn ngon. Sẽ giới thiệu cho bạn bè.',TIMESTAMP'2025-05-08 07:34:49');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (129,104,1,5,'Resort tuyệt vời nhất từng trải nghiệm! Kiến trúc Tây Ban Nha sang trọng, bãi biển riêng tuyệt đẹp. Villa có hồ bơi riêng rất ấn tượng. Spa YHI đẳng cấp thế giới. Dịch vụ hoàn hảo!',TIMESTAMP'2025-05-23 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (130,104,2,5,'Melia Ho Tram thực sự là thiên đường nghỉ dưỡng! Sân golf 18 lỗ tuyệt vời, bãi biển dài 1km rất đẹp. Phòng rộng rãi, view biển tuyệt vời. Buffet sáng đa dạng và ngon.',TIMESTAMP'2025-05-27 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (131,104,3,4,'Resort đẹp, tiện nghi hiện đại. Hồ bơi và khu vui chơi trẻ em tuyệt vời. Nhân viên phục vụ chuyên nghiệp. Chỉ có điều giá hơi cao nhưng xứng đáng với chất lượng.',TIMESTAMP'2025-05-19 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (132,104,4,5,'Kỳ nghỉ hoàn hảo tại Melia! Villa 2 phòng ngủ rộng rãi, có hồ bơi riêng tuyệt vời. Spa thư giãn đẳng cấp. Nhà hàng có món ăn ngon. Sẽ quay lại chắc chắn!',TIMESTAMP'2025-05-13 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (133,104,5,5,'Trải nghiệm tuyệt vời! Thiết kế resort rất đẹp, bãi biển sạch và yên tĩnh. Dịch vụ đưa đón sân bay tiện lợi. Phòng Classic hướng biển có view tuyệt đẹp. Highly recommended!',TIMESTAMP'2025-05-31 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (134,104,6,4,'Resort 5 sao chất lượng cao. Kiến trúc độc đáo, không gian rộng rãi. Sân golf đẹp, phù hợp cho golfer. Dịch vụ tốt, nhân viên thân thiện. Giá cả hợp lý cho resort đẳng cấp.',TIMESTAMP'2025-05-16 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (135,104,7,5,'Melia Ho Tram là resort tốt nhất vùng Hồ Tràm! Villa Tổng Thống sang trọng bậc nhất. Spa YHI thư giãn tuyệt vời. Bãi biển riêng yên tĩnh. Dịch vụ butler chuyên nghiệp.',TIMESTAMP'2025-05-25 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (136,104,8,4,'Resort đẹp, vị trí tuyệt vời gần Hồ Chí Minh. Phòng Premium rộng rãi, tiện nghi đầy đủ. Hồ bơi và beach club tuyệt vời. Nhà hàng có món ăn ngon. Sẽ giới thiệu cho bạn bè.',TIMESTAMP'2025-05-21 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (137,104,9,5,'Nghỉ dưỡng đẳng cấp quốc tế! Thiết kế kiến trúc Tây Ban Nha rất ấn tượng. Villa có hồ bơi riêng tuyệt vời. Spa và gym hiện đại. Bãi biển đẹp, nước trong xanh. Perfect vacation!',TIMESTAMP'2025-05-29 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (138,104,10,5,'Lần đầu đến Melia và rất ấn tượng! Suite Junior rộng rãi, view biển tuyệt đẹp. Dịch vụ concierge chu đáo. Kids club tuyệt vời cho trẻ em. Buffet đa dạng và chất lượng cao.',TIMESTAMP'2025-06-01 07:35:04');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (139,105,1,4,'Lang Co Beach Resort có vị trí tuyệt đẹp tại vịnh Lăng Cô. Bãi biển cát trắng dài, nước biển trong xanh. Phòng sạch sẽ, view đẹp. Nhân viên thân thiện. Buffet sáng đa dạng. Giá cả hợp lý cho resort 4 sao.',TIMESTAMP'2025-05-26 07:35:18');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (140,105,2,5,'Kỳ nghỉ tuyệt vời tại Lăng Cô! Resort có thiết kế hài hòa với thiên nhiên. Hồ bơi đẹp, spa thư giãn. Vị trí thuận lợi gần Huế và Đà Nẵng. Villa hướng biển có view tuyệt đẹp. Sẽ quay lại!',TIMESTAMP'2025-05-20 07:35:18');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (141,105,3,4,'Resort đẹp với bãi biển riêng tuyệt vời. Phòng Deluxe rộng rãi, tiện nghi đầy đủ. Nhà hàng có món hải sản tươi ngon. Dịch vụ tốt. Vị trí lý tưởng để khám phá Huế và Hội An.',TIMESTAMP'2025-05-14 07:35:18');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (142,105,4,5,'Lang Co thực sự là một trong những bãi biển đẹp nhất Việt Nam! Resort có thiết kế đẹp, hòa mình vào thiên nhiên. Suite Junior có ban công riêng tuyệt vời. Dịch vụ chu đáo.',TIMESTAMP'2025-05-29 07:35:18');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (143,105,5,4,'Nghỉ dưỡng tuyệt vời tại vịnh Lăng Cô! Bãi biển dài 10km rất ấn tượng. Phòng Superior hướng biển có view đẹp. Hồ bơi và khu vui chơi trẻ em tốt. Giá cả phù hợp với chất lượng.',TIMESTAMP'2025-05-22 07:35:18');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (144,105,6,5,'Resort tuyệt đẹp giữa núi và biển! Vị trí độc đáo của vịnh Lăng Cô rất ấn tượng. Villa 2 phòng ngủ rộng rãi, phù hợp gia đình. Spa thư giãn sau ngày dài tham quan. Highly recommended!',TIMESTAMP'2025-05-17 07:35:18');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (145,105,7,4,'Kỳ nghỉ thú vị tại Lang Co Beach Resort! Bãi biển sạch, nước trong. Phòng Premium có thiết kế đẹp. Nhà hàng có view biển tuyệt vời. Dịch vụ đưa đón thuận tiện. Sẽ giới thiệu cho bạn bè.',TIMESTAMP'2025-05-24 07:35:18');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (146,105,8,5,'Trải nghiệm tuyệt vời tại một trong những vịnh đẹp nhất thế giới! Resort có thiết kế hài hòa với cảnh quan. Suite Gia Đình rộng rãi. Bãi biển riêng yên tĩnh. Perfect for relaxation!',TIMESTAMP'2025-05-31 07:35:18');
