INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (98,119,2,4,'Kỳ nghỉ tơ lụa thú vị tại Hội An! Silk Road Villa có thiết kế lụa tuyệt đẹp. Workshop dệt lụa thủ công. Spa thư giãn. Bảo tàng tơ lụa Việt Nam thú vị!',TIMESTAMP'2025-05-22 07:34:22');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (99,119,3,4,'Resort 4 sao với concept tơ lụa độc đáo! Silk Family Suite rộng rãi, phù hợp gia đình. Workshop dệt lụa giáo dục. Kids club văn hóa thú vị.',TIMESTAMP'2025-05-15 07:34:22');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (100,119,4,4,'Silk Road thực sự là con đường tơ lụa tuyệt vời! Silk Suite Deluxe có thiết kế lụa sang trọng. Làng lụa truyền thống. Workshop dệt lụa thủ công thú vị.',TIMESTAMP'2025-05-24 07:34:22');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (101,119,5,4,'Nghỉ dưỡng văn hóa tuyệt vời tại Hội An! Silk Road View có view làng lụa đẹp. Bảo tàng tơ lụa giáo dục. Gym hiện đại. Workshop dệt lụa thú vị.',TIMESTAMP'2025-05-18 07:34:22');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (102,119,6,4,'Resort tơ lụa với thiết kế tuyệt đẹp! Silk Road Villa có view làng lụa tuyệt vời. Workshop dệt lụa thủ công. Spa thư giãn. Dịch vụ đưa đón thuận tiện.',TIMESTAMP'2025-05-26 07:34:22');
INSERT INTO DANH_GIA (ID,ID_KHU_NGHI_DUONG,ID_KHACH_HANG,DIEM,NOI_DUNG,THOIGIAN_TAO) VALUES (103,119,7,4,'Silk Road Resort có concept tơ lụa rất sáng tạo! Silk Garden Room yên tĩnh. Workshop dệt lụa truyền thống đáng trải nghiệm. Bảo tàng tơ lụa thú vị.',TIMESTAMP'2025-05-20 07:34:22');
