/*Tổng hợp*/
-- Create tables

-- Tao Bang
CREATE TABLE FUNCTION(
  FUNCTION_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  FUNCTION_NAME VARCHAR2(100) UNIQUE NOT NULL
);
CREATE TABLE ROLE_GROUP (
  GROUP_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  GROUP_NAME VARCHAR2(100) UNIQUE NOT NULL,
  DESCRIPTION VARCHAR2(255),
  CREATED_AT DATE DEFAULT SYSDATE,
  IS_DELETED  NUMBER(1) DEFAULT 0 CHECK (IS_DELETED IN (0,1))
);

CREATE TABLE ROLE (
  ROLE_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  FUNCTION_ID NUMBER(10) REFERENCES FUNCTION(FUNCTION_ID),
  ADD_PERM NUMBER(1) NOT NULL,
  EDIT_PERM NUMBER(1) NOT NULL,
  DELETE_PERM NUMBER(1) NOT NULL,
  DOWNLOAD_PERM NUMBER(1) NOT NULL,
  VIEW_PERM NUMBER(1) NOT NULL,
  CREATED_AT DATE DEFAULT SYSDATE,
  IS_DELETED   NUMBER(1) DEFAULT 0 CHECK (IS_DELETED IN (0,1))
);

CREATE TABLE NGUOI_DUNG (
  USER_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  HO_TEN VARCHAR2(100) NOT NULL,
  EMAIL VARCHAR2(150) NOT NULL,
  SDT NVARCHAR2(10) NOT NULL, 
  CCCD NVARCHAR2(15) NOT NULL, 
  CREATED_AT DATE DEFAULT SYSDATE,
  UPDATE_AT DATE DEFAULT SYSDATE,
  IS_DELETED   NUMBER(1) DEFAULT 0 CHECK (IS_DELETED IN (0,1))
);

CREATE TABLE TAI_KHOAN (
  ACCOUNT_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  USER_ID NUMBER(10) REFERENCES NGUOI_DUNG(USER_ID),
  TEN_TAI_KHOAN NVARCHAR2(255) NOT NULL,
  MAT_KHAU NVARCHAR2(255) NOT NULL,
  TRANG_THAI VARCHAR2(20) DEFAULT 'ACTIVE' CHECK (TRANG_THAI IN('ACTIVE', 'INACTIVE')), -- 'ACTIVE' OR 'INACTIVE'
  CREATED_AT DATE DEFAULT SYSDATE,
  IS_DELETED   NUMBER(1) DEFAULT 0 CHECK (IS_DELETED IN (0,1))
);


CREATE TABLE ACCOUNT_TOKEN (
  TOKEN_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ACCOUNT_ID NUMBER(10) REFERENCES TAI_KHOAN(ACCOUNT_ID),
  TOKEN_VALUE VARCHAR2(500) UNIQUE NOT NULL,
  EXPIRES_AT DATE NOT NULL,
  ISSUED_AT DATE,
  IS_DELETED   NUMBER(1) DEFAULT 0 CHECK (IS_DELETED IN (0,1))
);

CREATE TABLE ACCOUNT_ROLE_GROUP (
  ACCOUNT_ID NUMBER(10) REFERENCES TAI_KHOAN(ACCOUNT_ID),
  ROLE_GROUP_ID NUMBER(10) REFERENCES ROLE_GROUP(GROUP_ID),
  PRIMARY KEY (ACCOUNT_ID, ROLE_GROUP_ID)
);

CREATE TABLE ASSIGN_ROLE_GROUP (
  ROLE_GROUP_ID NUMBER(10) REFERENCES ROLE_GROUP(GROUP_ID),
  ROLE_ID NUMBER(10) REFERENCES ROLE(ROLE_ID),
  PRIMARY KEY (ROLE_GROUP_ID, ROLE_ID)
);

CREATE TABLE ACCOUNT_ASSIGN_ROLE (
  ACCOUNT_ID NUMBER(10) REFERENCES TAI_KHOAN(ACCOUNT_ID),
  ROLE_ID NUMBER(10) REFERENCES ROLE(ROLE_ID),
  PRIMARY KEY (ACCOUNT_ID, ROLE_ID)
);

CREATE TABLE KHACH_HANG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_TAI_KHOAN NUMBER NOT NULL REFERENCES TAI_KHOAN(ACCOUNT_ID) UNIQUE,
  DIA_CHI NVARCHAR2(255),
  DIEM_TICH_LUY INT NOT NULL
);

CREATE TABLE DOI_TAC (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_TAI_KHOAN NUMBER NOT NULL REFERENCE TAI_KHOAN(ACCOUNT_ID) UNIQUE,
  DIA_CHI NVARCHAR2(255) NOT NULL,
  TAIKHOAN_NGANHANG NVARCHAR2(15) NOT NULL,
  TEN_TKNH NVARCHAR2(255) NOT NULL,
  TEN_NGANHANG NVARCHAR2(255) NOT NULL,
  SO_DU DECIMAL(12,2) DEFAULT 0 CHECK(SO_DU >= 0)
);

CREATE TABLE LICH_SU_RUT_TIEN (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_DOI_TAC NUMBER NOT NULL REFERENCES DOI_TAC(ID),
  SOTIEN DECIMAL(12,2) NOT NULL,
  THOIGIAN_TAO TIMESTAMP NOT NULL,
  THOIGIAN_RUTTIEN TIMESTAMP NOT NULL,
  TRANG_THAI NVARCHAR2(255) NOT NULL 
);

CREATE TABLE THANH_PHO (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  TEN_THANH_PHO NVARCHAR2(255) NOT NULL
);

CREATE TABLE QUAN (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_THANH_PHO NUMBER NOT NULL REFERENCES THANH_PHO(ID),
  TEN_QUAN NVARCHAR2(255) NOT NULL
);

CREATE TABLE PHUONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_QUAN NUMBER NOT NULL REFERENCES QUAN(ID),
  TEN_PHUONG NVARCHAR2(255) NOT NULL
);

CREATE TABLE KHU_NGHI_DUONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_DOI_TAC NUMBER NOT NULL REFERENCES DOI_TAC(ID),
  TEN NVARCHAR2(255) NOT NULL,
  DIA_CHI NVARCHAR2(255) NOT NULL,
  PHUONG_ID NUMBER NOT NULL REFERENCES PHUONG(ID),
  MO_TA NVARCHAR2(255) NOT NULL,
  IMG_360_URL NVARCHAR2(255) NOT NULL,
  DANH_GIA INT NOT NULL
);

CREATE TABLE HINH_KHU_NGHI_DUONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_KHU_NGHI_DUONG NUMBER NOT NULL REFERENCES KHU_NGHI_DUONG(ID),
  URL NVARCHAR2(255) NOT NULL
);

CREATE TABLE DANH_GIA (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_KHU_NGHI_DUONG NUMBER NOT NULL REFERENCES KHU_NGHI_DUONG(ID),
  ID_KHACH_HANG NUMBER NOT NULL REFERENCES KHACH_HANG(ID),
  DIEM INT NOT NULL,
  NOI_DUNG NVARCHAR2(1000),
  THOIGIAN_TAO TIMESTAMP NOT NULL
);

CREATE TABLE LOAI_PHONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_KHU_NGHI_DUONG NUMBER NOT NULL REFERENCES KHU_NGHI_DUONG(ID),
  TEN_LOAI_PHONG NVARCHAR2(255) NOT NULL,
  DIEN_TICH FLOAT NOT NULL,
  LOAI_PHONG_THEO_SO_LUONG NVARCHAR2(255) NOT NULL,
  LOAI_PHONG_THEO_TIEU_CHUAN NVARCHAR2(255) NOT NULL,
  SO_GIUONG INT NOT NULL,
  SO_NGUOI INT NOT NULL,
  GIA DECIMAL(12,2) NOT NULL
);

CREATE TABLE HINH_PHONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_LOAI_PHONG NUMBER NOT NULL REFERENCES LOAI_PHONG(ID),
  URL NVARCHAR2(255) NOT NULL
);

CREATE TABLE TIEN_ICH (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  LOAI_TIEN_ICH NVARCHAR2(255) NOT NULL,
  ICON_URL NVARCHAR2(255) NOT NULL
);

CREATE TABLE TIEN_ICH_PHONG (
  ID_PHONG NUMBER REFERENCES LOAI_PHONG(ID),
  ID_TIEN_ICH NUMBER REFERENCES TIEN_ICH(ID),
  PRIMARY KEY (ID_PHONG, ID_TIEN_ICH)
);

CREATE TABLE PHONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_LOAI_PHONG NUMBER NOT NULL REFERENCES LOAI_PHONG(ID),
  TRANG_THAI NVARCHAR2(255) NOT NULL
);

CREATE TABLE DICH_VU (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  TEN_DICH_VU NVARCHAR2(255) NOT NULL,
  MO_TA NVARCHAR2(255) NOT NULL
);

CREATE TABLE DICH_VU_KHU_NGHI_DUONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_DICH_VU NUMBER NOT NULL REFERENCES DICH_VU(ID),
  ID_RESORT NUMBER NOT NULL REFERENCES KHU_NGHI_DUONG(ID),
  GIA DECIMAL(12,2) NOT NULL
);

CREATE TABLE GOI_DAT_PHONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_LOAI_PHONG NUMBER NOT NULL REFERENCES LOAI_PHONG(ID),
  TONG_GIATIEN DECIMAL(12,2) NOT NULL
);

CREATE TABLE DICH_VU_MAC_DINH (
  ID_DICH_VU_KHU_NGHI_DUONG NUMBER NOT NULL REFERENCES DICH_VU_KHU_NGHI_DUONG(ID),
  ID_GOI_DAT_PHONG NUMBER NOT NULL REFERENCES GOI_DAT_PHONG(ID),
  GIAMGIA DECIMAL(12,2) NOT NULL,
  PRIMARY KEY (ID_DICH_VU_KHU_NGHI_DUONG, ID_GOI_DAT_PHONG)
);

CREATE TABLE DAT_PHONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_KHACH_HANG NUMBER NOT NULL REFERENCES KHACH_HANG(ID),
  THOI_GIAN_TAO TIMESTAMP NOT NULL,
  TRANG_THAI NVARCHAR2(255) NOT NULL,
  TONG_GIATIEN DECIMAL(12,2) NOT NULL,
  TAIKHOAN_NGANHANG NVARCHAR2(15),
  TEN_TKNH NVARCHAR2(255),
  TEN_NGANHANG NVARCHAR2(255)
);

CREATE TABLE GIAMGIA (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_LOAI_PHONG NUMBER NOT NULL REFERENCES LOAI_PHONG(ID),
  TEN_GIAMGIA NVARCHAR2(255) NOT NULL,
  LOAI_GIAMGIA NVARCHAR2(255) NOT NULL,
  GIA_TRI DECIMAL(12,2) NOT NULL,
  MUC_TOI_DA DECIMAL(12,2),
  NGAY_BAT_DAU TIMESTAMP NOT NULL,
  NGAY_KET_THUC TIMESTAMP NOT NULL,
  TRANG_THAI NVARCHAR2(255) NOT NULL
);

CREATE TABLE CHI_TIET_DAT_PHONG (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_DAT_PHONG NUMBER NOT NULL REFERENCES DAT_PHONG(ID),
  ID_GOI_DAT_PHONG NUMBER NOT NULL REFERENCES GOI_DAT_PHONG(ID),
  ID_GIAMGIA NUMBER NOT NULL REFERENCES GIAMGIA(ID),
  SO_LUONG_PHONG INT NOT NULL,
  SO_LUONG_DICH_VU_YEU_CAU INT NOT NULL,
  TONG_GIATIEN DECIMAL(12,2) NOT NULL,
  NGAY_BAT_DAU TIMESTAMP NOT NULL,
  NGAY_KET_THUC TIMESTAMP NOT NULL,
  TRANG_THAI NVARCHAR2(255) NOT NULL
);


CREATE TABLE DICH_VU_YEU_CAU (
  ID_DICH_VU_KHU_NGHI_DUONG NUMBER NOT NULL REFERENCES DICH_VU_KHU_NGHI_DUONG(ID),
  ID_CHI_TIET_DAT_PHONG NUMBER NOT NULL REFERENCES CHI_TIET_DAT_PHONG(ID),
  PRIMARY KEY (ID_DICH_VU_KHU_NGHI_DUONG, ID_CHI_TIET_DAT_PHONG)
);

CREATE TABLE KHO_MA_GIAM_GIA (
  ID_KHACH_HANG NUMBER NOT NULL REFERENCES KHACH_HANG(ID),
  ID_GIAMGIA NUMBER NOT NULL REFERENCES GIAMGIA(ID),
  PRIMARY KEY (ID_KHACH_HANG, ID_GIAMGIA)
);

CREATE TABLE HOA_DON (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_KHACH_HANG NUMBER NOT NULL REFERENCES KHACH_HANG(ID),
  ID_DOI_TAC NUMBER NOT NULL REFERENCES DOI_TAC(ID),
  ID_CHI_TIET_DAT_PHONG NUMBER NOT NULL REFERENCES CHI_TIET_DAT_PHONG(ID),
  TONG_GIATIEN DECIMAL(12,2) NOT NULL,
  THOIGIAN_THANHTOAN TIMESTAMP NOT NULL,
  HINH_THUC_THANH_TOAN NVARCHAR2(255) NOT NULL
);


CREATE TABLE THOIGIAN_PHONG_BAN (
  ID_HOA_DON NUMBER NOT NULL REFERENCES HOA_DON(ID),
  ID_PHONG NUMBER NOT NULL REFERENCES PHONG(ID),
  NGAY_BAT_DAU TIMESTAMP NOT NULL,
  NGAY_KET_THUC TIMESTAMP NOT NULL
);

CREATE TABLE DOI_DIEM (
  ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ID_MAGIAM NUMBER NOT NULL REFERENCES GIAMGIA(ID),
  GIA_TRI INT
);

-- CONSTRAINT TABLE CONSTRAINT
ALTER TABLE NGUOI_DUNG ADD CONSTRAINT NGUOI_DUNG_EMAIL UNIQUE (EMAIL);
ALTER TABLE TAI_KHOAN ADD CONSTRAINT TAI_KHOAN_TENTAIKHOAN UNIQUE (TEN_TAI_KHOAN);
ALTER TABLE KHU_NGHI_DUONG ADD CONSTRAINT KHU_NGHI_DUONG_CUNG_DOITAC UNIQUE (TEN, ID_DOI_TAC);
ALTER TABLE THANH_PHO ADD CONSTRAINT TEN_THANH_PHO UNIQUE (TEN_THANH_PHO);
ALTER TABLE QUAN ADD CONSTRAINT QUAN_TRONG_THANHPHO UNIQUE (TEN_QUAN, ID_THANH_PHO);
ALTER TABLE TAI_KHOAN ADD CONSTRAINT CK_TAIKHOAN_TRANGTHAI  CHECK (TRANG_THAI IN ('ACTIVE', 'INACTIVE'));
ALTER TABLE DANH_GIA ADD CONSTRAINT CK_DIEM_DANHGIA CHECK (DIEM BETWEEN 1 AND 5);
ALTER TABLE LICH_SU_RUT_TIEN ADD CONSTRAINT CK_RUTTIEN_SOTIEN CHECK (SOTIEN > 0);
ALTER TABLE LOAI_PHONG ADD CONSTRAINT CK_LOAIPHONG_GIA  CHECK (GIA > 0);
ALTER TABLE NGUOI_DUNG ADD CONSTRAINT CK_NGUOIDUNG_SDT CHECK (REGEXP_LIKE(SDT, '^\d{10}$'));

-- Trigger
CREATE OR REPLACE TRIGGER TRG_CHECK_URL_HINH_KHUNGHIDUONG
BEFORE UPDATE ON HINH_KHU_NGHI_DUONG
FOR EACH ROW
BEGIN
	IF NOT REGEXP_LIKE(:NEW.URL, '^https?://[a-zA-Z0-9\-._~:/?#\[\]@!$&''()*+,;=]+$') THEN
		RAISE_APPLICATION_ERROR(-20002, 'URL không hợp lệ.');
	END IF;
END;
/


CREATE OR REPLACE TRIGGER TRG_CHECK_GIA_TRI_GIAMGIA
BEFORE INSERT ON GIAMGIA
FOR EACH ROW
BEGIN
	IF :NEW.LOAI_GIAMGIA = 'Phần trăm' THEN
		IF :NEW.GIA_TRI < 0 OR :NEW.GIA_TRI > 100 THEN
			RAISE_APPLICATION_ERROR(-20008, 'Lỗi: Mã giảm giá dạng Phần trăm phải có giá trị từ 0 đến 100.');END IF;
	
	ELSIF :NEW.LOAI_GIAMGIA = 'Cố định' THEN
		IF :NEW.GIA_TRI <= 0 THEN
			RAISE_APPLICATION_ERROR(-20009, 'Lỗi: Mã giảm giá dạng Cố định phải có giá trị > 0.');
		END IF;
	ELSE
		RAISE_APPLICATION_ERROR(-20010,'Loại mã giảm giá không hợp lệ.');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_CHECK_GIA_TRI_GIAMGIA
BEFORE INSERT ON GIAMGIA
FOR EACH ROW
BEGIN
	IF :NEW.LOAI_GIAMGIA = 'Phần trăm' THEN
		IF :NEW.GIA_TRI < 0 OR :NEW.GIA_TRI > 100 THEN
			RAISE_APPLICATION_ERROR(-20008, 'Lỗi: Mã giảm giá dạng Phần trăm phải có giá trị từ 0 đến 100.');END IF;
	
	ELSIF :NEW.LOAI_GIAMGIA = 'Cố định' THEN
		IF :NEW.GIA_TRI <= 0 THEN
			RAISE_APPLICATION_ERROR(-20009, 'Lỗi: Mã giảm giá dạng Cố định phải có giá trị > 0.');
		END IF;
	ELSE
		RAISE_APPLICATION_ERROR(-20010,'Loại mã giảm giá không hợp lệ.');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_SO_LUONG_HINH_KND
FOR DELETE ON HINH_KHU_NGHI_DUONG
COMPOUND TRIGGER

          TYPE t_id_knd_tab IS TABLE OF                HINH_KHU_NGHI_DUONG.ID_KHU_NGHI_DUONG%TYPE INDEX BY PLS_INTEGER;
          v_knd_ids t_id_knd_tab;
          v_index   INTEGER := 0;

          BEFORE EACH ROW IS
          BEGIN
                      v_index := v_index + 1;
                      v_knd_ids(v_index) := :OLD.ID_KHU_NGHI_DUONG;
          END BEFORE EACH ROW;

          AFTER STATEMENT IS
          v_count INTEGER;
          BEGIN
                     FOR i IN 1 .. v_knd_ids.COUNT 
                     LOOP
                                  SELECT COUNT(*) INTO v_count
                                  FROM HINH_KHU_NGHI_DUONG
                                  WHERE ID_KHU_NGHI_DUONG = v_knd_ids(i);
         
                                  IF v_count < 1 THEN
                                                 RAISE_APPLICATION_ERROR(-20020, 'Không thể xóa hình ảnh của khu nghỉ dưỡng, mỗi khu phải có ít nhất một hình.');
                                  END IF;
                      END LOOP;
          END AFTER STATEMENT;
END TRG_SO_LUONG_HINH_KND;
/

CREATE OR REPLACE TRIGGER TRG_TONGGIATIEN_GOIDATPHONG
BEFORE INSERT OR UPDATE ON GOI_DAT_PHONG
FOR EACH ROW
DECLARE

           v_gia_phong      DECIMAL(12,2);
           v_gia_dv         DECIMAL(12,2);
           v_giamgia_dv     DECIMAL(12,2);
           v_tong		   DECIMAL(12,2);

BEGIN

	SELECT GIA INTO v_gia_phong
	FROM LOAI_PHONG
	WHERE ID = :NEW.ID_LOAI_PHONG;
	
	SELECT SUM(DVKND.GIA)
	INTO v_gia_dv
	FROM DICH_VU_MAC_DINH DVMD
	JOIN DICH_VU_KHU_NGHI_DUONG DVKND ON DVMD.ID_DICH_VU_KHU_NGHI_DUONG = DVKND.ID
	WHERE DVMD.ID_GOI_DAT_PHONG = :NEW.ID;
	
	SELECT SUM(DVMD.GIAMGIA)
	INTO v_giamgia_dv
	FROM DICH_VU_MAC_DINH DVMD
	WHERE DVMD.ID_GOI_DAT_PHONG = :NEW.ID;

	v_tong := v_gia_phong + v_gia_dv - v_giamgia_dv;

	IF :NEW.TONG_GIATIEN <> v_tong THEN
		RAISE_APPLICATION_ERROR(-20031, 'Tổng giá tiền gói đặt phòng không đúng.');
	END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_DAT_PHONG
AFTER UPDATE ON DAT_PHONG
FOR EACH ROW
BEGIN
    IF :OLD.TRANG_THAI != :NEW.TRANG_THAI THEN
        UPDATE CHI_TIET_DAT_PHONG
        SET
            TRANG_THAI = :NEW.TRANG_THAI
        WHERE
            ID_DAT_PHONG = :NEW.ID;
    END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_LOAI_PHONG 
AFTER UPDATE ON LOAI_PHONG FOR EACH ROW
BEGIN
    IF :OLD.GIA != :NEW.GIA THEN

        UPDATE GOI_DAT_PHONG GDP
        SET
            TONG_GIATIEN = TONG_GIATIEN + (
                :NEW.GIA - :OLD.GIA
            )
        WHERE
            GDP.ID_LOAI_PHONG = :NEW.ID;
    END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_DICH_VU_KHU_NGHI_DUONG 
AFTER UPDATE ON DICH_VU_KHU_NGHI_DUONG FOR EACH ROW
BEGIN
    IF :OLD.GIA != :NEW.GIA THEN
        UPDATE GOI_DAT_PHONG
        SET
            TONG_GIATIEN = TONG_GIATIEN + (
                :NEW.GIA - :OLD.GIA
            )
        WHERE
            ID IN (
                SELECT
                    ID_GOI_DAT_PHONG
                FROM
                    DICH_VU_MAC_DINH
                WHERE
                    ID_DICH_VU_KHU_NGHI_DUONG = :NEW.ID
            );
    END IF;


    IF :OLD.IS_DELETED != :NEW.IS_DELETED THEN
        IF :NEW.IS_DELETED = 1 THEN
            UPDATE GOI_DAT_PHONG
            SET
                TONG_GIATIEN = TONG_GIATIEN - :NEW.GIA
            WHERE
                ID IN (
                    SELECT
                        ID_DICH_VU_KHU_NGHI_DUONG
                    FROM
                        DICH_VU_MAC_DINH
                    WHERE
                        ID_DICH_VU_KHU_NGHI_DUONG = :NEW.ID
                );
        ELSIF :NEW.IS_DELETED = 0 THEN
            UPDATE GOI_DAT_PHONG
            SET
                TONG_GIATIEN = TONG_GIATIEN + :NEW.GIA
            WHERE
                ID IN (
                    SELECT
                        ID_DICH_VU_KHU_NGHI_DUONG
                    FROM
                        DICH_VU_MAC_DINH
                    WHERE
                        ID_DICH_VU_KHU_NGHI_DUONG = :NEW.ID
                );
        END IF;
    END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_GOI_DAT_PHONG 
AFTER UPDATE OR DELETE ON GOI_DAT_PHONG FOR EACH ROW 
BEGIN 
            IF UPDATING THEN 
                       IF :OLD.TONG_GIATIEN != :NEW.TONG_GIATIEN THEN
                                    UPDATE CHI_TIET_DAT_PHONG CTDP
                                    SET CTDP.TONG_GIATIEN = CTDP.TONG_GIATIEN + ( :NEW.TONG_GIATIEN - :OLD.TONG_GIATIEN )
                                    WHERE CTDP.ID_GOI_DAT_PHONG = :NEW.ID;
                       END IF;
            END IF;
            
            IF DELETING THEN
                       UPDATE CHI_TIET_DAT_PHONG CTDP
                       SET CTDP.TONG_GIATIEN = CTDP.TONG_GIATIEN - :OLD.TONG_GIATIEN
                       WHERE CTDP.ID_GOI_DAT_PHONG = :NEW.ID;
            END IF;
END;
/


CREATE OR REPLACE TRIGGER TRG_TINH_TONG_GIATIEN_CHI_TIET_DP BEFORE INSERT OR UPDATE ON CHI_TIET_DAT_PHONG FOR EACH ROW DECLARE V_GIATRI NUMBER := 0;
V_LOAIGIAMGIA NVARCHAR2(510);
V_GIAGOC NUMBER;
V_MUCTOIDA NUMBER;
BEGIN
    SELECT
        TONG_GIATIEN INTO V_GIAGOC
    FROM
        GOI_DAT_PHONG
    WHERE
        ID = :NEW.ID_GOI_DAT_PHONG;


    IF UPDATING AND :NEW.ID_GIAMGIA IS NOT NULL THEN
        SELECT
            LOAI_GIAMGIA,
            GIA_TRI,
            MUC_TOI_DA INTO V_LOAIGIAMGIA,
            V_GIATRI,
            V_MUCTOIDA
        FROM
            GIAMGIA
        WHERE
            ID = :NEW.ID_GIAMGIA;
        IF V_LOAIGIAMGIA = 'PERCENT' THEN
            :NEW.TONG_GIATIEN := V_GIAGOC * (1 - V_GIATRI / 100);
            IF :NEW.TONG_GIATIEN >= V_MUCTOIDA THEN
                :NEW.TONG_GIATIEN := V_MUCTOIDA;
            END IF;
        ELSIF V_LOAIGIAMGIA = 'AMOUNT' THEN
            :NEW.TONG_GIATIEN := V_GIAGOC - V_GIATRI;
        END IF;
    ELSE
        :NEW.TONG_GIATIEN := V_GIAGOC;
    END IF;
END;


CREATE OR REPLACE TRIGGER TRG_UPDATE_DIEM_TRUNG_BINH
AFTER INSERT ON DANH_GIA
FOR EACH ROW
DECLARE
  v_avg_diem NUMBER(3,1);
BEGIN
  SELECT ROUND(AVG(DIEM), 1)
  INTO v_avg_diem
  FROM DANH_GIA
  WHERE ID_KHU_NGHI_DUONG = :NEW.ID_KHU_NGHI_DUONG;
  UPDATE KHU_NGHI_DUONG
  SET DANH_GIA = v_avg_diem
  WHERE ID = :NEW.ID_KHU_NGHI_DUONG;
END;
/

CREATE OR REPLACE TRIGGER TRG_CHECK_SO_DU_BEFORE_RUTTIEN
BEFORE INSERT ON LICH_SU_RUT_TIEN
FOR EACH ROW
DECLARE
  v_sodu_hientai DOI_TAC.SO_DU%TYPE;
BEGIN
  SELECT SO_DU
  INTO v_sodu_hientai
  FROM DOI_TAC
  WHERE ID = :NEW.ID_DOI_TAC
  FOR UPDATE;

  IF v_sodu_hientai - :NEW.SOTIEN < 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'Số dư không đủ để rút tiền!');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_UPDATE_DIEM_TICH_LUY_KHI_DOI_MA
AFTER INSERT ON KHO_MA_GIAM_GIA
FOR EACH ROW
DECLARE
  v_gia_tri NUMBER(12,2);
BEGIN
  -- Lấy số điểm cần trừ tương ứng mã giảm giá
  SELECT GIA_TRI INTO v_gia_tri
  FROM GIAMGIA
  WHERE ID = :NEW.ID_GIAMGIA;

  -- Trừ điểm tích lũy của khách hàng
  UPDATE KHACH_HANG
  SET DIEM_TICH_LUY = DIEM_TICH_LUY - v_gia_tri
  WHERE ID = :NEW.ID_KHACH_HANG;
END;
/

CREATE OR REPLACE TRIGGER TRG_UPDATE_SODU_DOITAC
AFTER UPDATE OF TINH_TRANG ON CHI_TIET_DAT_PHONG
FOR EACH ROW
DECLARE
  v_id_doi_tac NUMBER;
  v_tien_doi_tac NUMBER;
  v_sodu_hientai NUMBER;
BEGIN
  IF :NEW.TRANG_THAI = 'DA_HUY' AND :OLD.TRANG_THAI != 'DA_HUY' THEN
    -- Lấy ID_DOI_TAC từ HOA_DON dựa vào ID_CHI_TIET_DAT_PHONG
    SELECT hd.ID_DOI_TAC
    INTO v_id_doi_tac
    FROM HOA_DON hd
    WHERE hd.ID_CHI_TIET_DAT_PHONG = :NEW.ID;

    -- Tính số tiền đối tác được hưởng (80% tổng giá tiền)
    v_tien_doi_tac := ROUND(:NEW.TONG_GIATIEN * 0.8, 0);

    -- Lấy số dư hiện tại của đối tác
    SELECT SO_DU
    INTO v_sodu_hientai
    FROM DOI_TAC
    WHERE ID = v_id_doi_tac;

    -- Cập nhật số dư mới (trừ đi tiền đối tác)
    UPDATE DOI_TAC
    SET SO_DU = v_sodu_hientai - v_tien_doi_tac
    WHERE ID = v_id_doi_tac;
  END IF;
END;
/

-- Procedure
CREATE OR REPLACE PROCEDURE XEM_THONG_TIN_DOI_TAC (
            p_cursor OUT SYS_REFCURSOR
)
AS
BEGIN
           OPEN p_cursor FOR
                   SELECT dt.ID AS DOI_TAC_ID, nd.HO_TEN, nd.EMAIL, nd.SDT,  nd.CCCD, tk.TEN_TAI_KHOAN, dt.DIA_CHI, dt.TAIKHOAN_NGANHANG,  dt.TEN_TKNH, dt.TEN_NGANHANG, dt.SO_DU, tk.TRANG_THAI AS TRANG_THAI_TAI_KHOAN, nd.CREATED_AT AS NGAY_TAO_NGUOI_DUNG
                            FROM DOI_TAC dt
                            JOIN TAI_KHOAN tk ON dt.ID_TAI_KHOAN = tk.ACCOUNT_ID
                            JOIN NGUOI_DUNG nd ON tk.USER_ID = nd.USER_ID
                            WHERE dt.SO_DU >= 0  AND tk.IS_DELETED = 0 
                                                AND nd.IS_DELETED = 0;
END;
/

CREATE OR REPLACE PROCEDURE TIM_KIEM_DOI_TAC (
          p_tu_khoa IN VARCHAR2,
          p_cursor  OUT SYS_REFCURSOR
)
AS
BEGIN
         OPEN p_cursor FOR
                       SELECT dt.ID AS DOI_TAC_ID, nd.HO_TEN, nd.EMAIL, nd.SDT,  nd.CCCD, tk.TEN_TAI_KHOAN, dt.DIA_CHI, dt.TAIKHOAN_NGANHANG, dt.TEN_TKNH, dt.TEN_NGANHANG, dt.SO_DU, tk.TRANG_THAI AS TRANG_THAI_TAI_KHOAN, nd.CREATED_AT AS NGAY_TAO_NGUOI_DUNG
                            FROM DOI_TAC dt
                            JOIN TAI_KHOAN tk ON dt.ID_TAI_KHOAN = tk.ACCOUNT_ID
                            JOIN NGUOI_DUNG nd ON tk.USER_ID = nd.USER_ID
                            WHERE (LOWER(nd.HO_TEN) LIKE '%' || LOWER(p_tu_khoa) || '%'  OR nd.SDT LIKE '%' || p_tu_khoa || '%') AND dt.SO_DU >= 0 AND tk.IS_DELETED = 0 AND nd.IS_DELETED = 0;
END;
/

CREATE OR REPLACE PROCEDURE SUA_THONG_TIN_DOI_TAC (
               p_id               IN NUMBER,
               p_dia_chi          IN NVARCHAR2,
               p_taikhoan_nganhang IN NVARCHAR2,
               p_ten_tknh         IN NVARCHAR2,
               p_ten_nganhang     IN NVARCHAR2,
               p_so_du            IN DECIMAL
)
AS
BEGIN
               -- Kiểm tra tồn tại
               IF NOT EXISTS ( SELECT 1 FROM DOI_TAC WHERE ID = p_id ) THEN
                            RAISE_APPLICATION_ERROR(-20001, 'Đối tác không tồn tại.');
               END IF;

               -- Cập nhật thông tin
               UPDATE DOI_TAC
               SET DIA_CHI = p_dia_chi,
                       TAIKHOAN_NGANHANG = p_taikhoan_nganhang,
                       TEN_TKNH = p_ten_tknh,
                       TEN_NGANHANG = p_ten_nganhang,
                       SO_DU = p_so_du
               WHERE ID = p_id;
               
               COMMIT;
END;
/

CREATE OR REPLACE PROCEDURE THEM_DOI_TAC (
                 p_id_tai_khoan        IN NUMBER,
                 p_dia_chi             IN NVARCHAR2,
                 p_taikhoan_nganhang   IN NVARCHAR2,
                 p_ten_tknh            IN NVARCHAR2,
                 p_ten_nganhang        IN NVARCHAR2,
                 p_so_du               IN DECIMAL
)
AS
                 v_count NUMBER;
BEGIN
                 -- Kiểm tra tài khoản đã tồn tại hay chưa
                 SELECT COUNT(*) INTO v_count
                 FROM TAI_KHOAN
                 WHERE ACCOUNT_ID = p_id_tai_khoan AND IS_DELETED = 0;

                 IF v_count = 0 THEN
                               RAISE_APPLICATION_ERROR(-20001, 'Tài khoản không tồn tại hoặc đã bị xóa.');
                 END IF;

                 SELECT COUNT(*) INTO v_count
                 FROM DOI_TAC
                 WHERE ID_TAI_KHOAN = p_id_tai_khoan;

                 IF v_count > 0 THEN
                            RAISE_APPLICATION_ERROR(-20002, 'Tài khoản đã được liên kết với một đối tác.');
                 END IF;

 TAIKHOAN_NGANHANG, TEN_TKNH, TEN_NGANHANG, SO_DU) VALUES (
                  p_id_tai_khoan, p_dia_chi, p_taikhoan_nganhang, p_ten_tknh, p_ten_nganhang, p_so_du);
                 COMMIT;
END;
/

CREATE OR REPLACE PROCEDURE XOA_DOI_TAC (
                 p_id IN NUMBER
)
AS
                 v_count NUMBER;
BEGIN

                 SELECT COUNT(*) INTO v_count
                 FROM DOI_TAC
                 WHERE ID = p_id;

                 IF v_count = 0 THEN
                             RAISE_APPLICATION_ERROR(-20001, 'Đối tác không tồn tại.');
                 END IF;

                 DELETE FROM DOI_TAC WHERE ID = p_id;
                COMMIT;
END;
/

CREATE OR REPLACE PROCEDURE TAO_TAI_KHOAN_DOI_TAC (
                 p_ho_ten            IN VARCHAR2,
                 p_email             IN VARCHAR2,
                 p_sdt               IN NVARCHAR2,
                 p_cccd              IN NVARCHAR2,
                 p_ten_tai_khoan     IN NVARCHAR2,
                 p_mat_khau          IN NVARCHAR2,
                 p_dia_chi           IN NVARCHAR2,
                 p_taikhoan_nganhang IN NVARCHAR2,
                 p_ten_tknh          IN NVARCHAR2,
                 p_ten_nganhang      IN NVARCHAR2,
                 p_so_du             IN DECIMAL
)
AS
                 v_user_id     NUMBER;
                 v_account_id  NUMBER;
BEGIN

                 VALUES (p_ho_ten, p_email, p_sdt, p_cccd)
                 RETURNING USER_ID INTO v_user_id;

            VALUES (v_user_id, p_ten_tai_khoan, p_mat_khau)
            RETURNING ACCOUNT_ID INTO v_account_id;

                INTO DOI_TAC(ID_TAI_KHOAN, DIA_CHI, TAIKHOAN_NGANHANG, TEN_TKNH, TEN_NGANHANG, SO_DU)
    VALUES (v_account_id, p_dia_chi, p_taikhoan_nganhang, p_ten_tknh, p_ten_nganhang, p_so_du);
                COMMIT;
END;
/

CREATE OR REPLACE PROCEDURE XemChiTietKhuNghiDuong (
                p_resort_id         IN  NUMBER,
                p_resort_cursor     OUT SYS_REFCURSOR
)
IS
                v_resort_exists     NUMBER;
                ResortNotFound      EXCEPTION;
BEGIN
                 -- Kiểm tra khu nghỉ dưỡng có tồn tại không
                 SELECT COUNT(*)
                 INTO v_resort_exists
                 FROM KHU_NGHI_DUONG
                 WHERE ID = p_resort_id;

                 IF v_resort_exists = 0 THEN
                                   RAISE ResortNotFound;
                 END IF;

                 -- Cursor thông tin chi tiết resort
                  OPEN p_resort_cursor FOR
                                 -- Thông tin cơ bản resort
                                 -- Thông tin địa lý
                                 -- Thông tin đối tác
                                 -- Thống kê đánh giá
                                 -- Thống kê loại phòng
                                SELECT knd.ID as resort_id, knd.TEN as ten_resort,
knd.DIA_CHI as dia_chi, knd.IMG_360_URL, knd.DANH_GIA, p.TEN_PHUONG, q.TEN_QUAN, tp.TEN_THANH_PHO, dt.ID as doi_tac_id,u.HO_TEN as ho_ten_doi_tac,  u.SDT as sdt_doi_tac, u.EMAIL as email_doi_tac,
                                COUNT(dg.ID) as so_luong_danh_gia,
                                ROUND(AVG(dg.DIEM), 1) as diem_trung_binh,
                                COUNT(DISTINCT lp.ID) as so_loai_phong,
                                MIN(lp.GIA) as gia_thap_nhat,
                                MAX(lp.GIA) as gia_cao_nhat
                                FROM KHU_NGHI_DUONG knd
                                JOIN PHUONG p ON knd.PHUONG_ID = p.ID
                                JOIN QUAN q ON p.ID_QUAN = q.ID
                                JOIN THANH_PHO tp ON q.ID_THANH_PHO = tp.ID
                                JOIN DOI_TAC dt ON knd.ID_DOI_TAC = dt.ID
                                LEFT JOIN DANH_GIA dg ON knd.ID = dg.ID_KHU_NGHI_DUONG
                                LEFT JOIN LOAI_PHONG lp ON knd.ID = lp.ID_KHU_NGHI_DUONG
                               JOIN TAI_KHOAN tk ON dt.ID_TAI_KHOAN = tk.ACCOUNT_ID
                               JOIN NGUOI_DUNG u ON tk.USER_ID = u.USER_ID
                               WHERE knd.ID = p_resort_id
                               GROUP BY knd.ID, knd.TEN, knd.DIA_CHI, knd.IMG_360_URL, knd.DANH_GIA, p.TEN_PHUONG, q.TEN_QUAN, tp.TEN_THANH_PHO, dt.ID, u.HO_TEN, u.SDT, u.EMAIL;

EXCEPTION
            WHEN ResortNotFound THEN
                       RAISE_APPLICATION_ERROR(-20001, 'Không tìm thấy thông tin khu nghỉ dưỡng');
            WHEN OTHERS THEN
             -- Đóng các cursor nếu có lỗi
             IF p_resort_cursor%ISOPEN THEN
                       CLOSE p_resort_cursor;
             END IF;
             RAISE_APPLICATION_ERROR(-20999, 'Lỗi hệ thống khi xem chi tiết khu nghỉ dưỡng');
END;
/

CREATE OR REPLACE PROCEDURE TimResortVaPhong (
    p_tu_khoa   IN  VARCHAR2,
    p_ngay_nhan IN  TIMESTAMP,
    p_ngay_tra  IN  TIMESTAMP,
    p_so_nguoi  IN  NUMBER,
    p_output    OUT SYS_REFCURSOR
)
IS
BEGIN
    OPEN p_output FOR
        SELECT
            knd.ID AS id,
            knd.ten AS ten_resort,
            knd.dia_chi || ', ' || p_ph.ten_phuong || ', ' ||
            p_quan.ten_quan || ', ' || p_tp.ten_thanh_pho           AS dia_chi,
            MIN(gdp.tong_giatien)                                   AS gia_thap_nhat,
            knd.img_360_url,
            knd.danh_gia,
            COUNT(DISTINCT dg.ID) AS so_luong_danh_gia,
          ( CASE WHEN REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(p_ph.ten_phuong))) THEN 1 ELSE 0 END +
            CASE WHEN REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(p_quan.ten_quan))) THEN 1 ELSE 0 END +
            CASE WHEN REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(p_tp.ten_thanh_pho))) THEN 1 ELSE 0 END +
            CASE WHEN REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(knd.ten)))        THEN 1 ELSE 0 END +
            CASE WHEN REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(knd.dia_chi)))    THEN 1 ELSE 0 END
          )                                                         AS relevance_score

        FROM   khu_nghi_duong          knd
        JOIN   phuong                  p_ph   ON knd.phuong_id       = p_ph.id
        JOIN   quan                    p_quan ON p_ph.id_quan        = p_quan.id
        JOIN   thanh_pho               p_tp   ON p_quan.id_thanh_pho = p_tp.id
        JOIN   phong                   p      ON p.id_khu_nghi_duong = knd.id
        JOIN   loai_phong              lp     ON lp.id               = p.id_loai_phong
        LEFT   JOIN goi_dat_phong      gdp    ON gdp.id_loai_phong   = lp.id
        LEFT JOIN   danh_gia                dg     ON dg.ID_KHU_NGHI_DUONG= knd.id
        WHERE  (   REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(p_ph.ten_phuong)))
                OR REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(p_quan.ten_quan)))
                OR REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(p_tp.ten_thanh_pho)))
                OR REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(knd.ten)))
                OR REGEXP_LIKE(TRIM(LOWER(p_tu_khoa)), TRIM(LOWER(knd.dia_chi))) )
          AND  p.TRANG_THAI = 'Available'
          AND  lp.so_nguoi  >= p_so_nguoi
          AND  NOT EXISTS (
                 SELECT 1
                 FROM   thoigian_phong_ban tpb
                 WHERE  tpb.id_phong = p.id
                   AND  tpb.ngay_bat_dau < p_ngay_tra
                   AND  tpb.ngay_ket_thuc > p_ngay_nhan )
        GROUP BY
              knd.id,
              knd.ten, knd.dia_chi,
              p_ph.ten_phuong, p_quan.ten_quan, p_tp.ten_thanh_pho,
              knd.img_360_url, knd.danh_gia
        ORDER BY relevance_score DESC;
END;
/

CREATE OR REPLACE PROCEDURE XEM_BIEN_DONG_SO_DU (
  p_doi_tac_id IN NUMBER,
  p_cursor     OUT SYS_REFCURSOR
)
AS
BEGIN
  OPEN p_cursor FOR
    SELECT ngay, SUM(thay_doi_sodu) AS thay_doi_sodu
    FROM (
        SELECT 
            TRUNC(hd.THOIGIAN_THANHTOAN) AS ngay,
            SUM(hd.TONG_GIATIEN) AS thay_doi_sodu
        FROM HOA_DON hd
        JOIN DOI_TAC dt ON hd.ID_DOI_TAC = dt.ID
        WHERE dt.ID = p_doi_tac_id
          AND EXTRACT(YEAR FROM hd.THOIGIAN_THANHTOAN) = EXTRACT(YEAR FROM SYSDATE)
        GROUP BY TRUNC(hd.THOIGIAN_THANHTOAN)

        UNION ALL

        SELECT 
            TRUNC(rt.THOIGIAN_RUT_TIEN) AS ngay,
            -SUM(rt.SOTIEN) AS thay_doi_sodu
        FROM LICH_SU_RUT_TIEN rt
        WHERE rt.ID_DOI_TAC = p_doi_tac_id
          AND EXTRACT(YEAR FROM rt.THOIGIAN_RUT_TIEN) = EXTRACT(YEAR FROM SYSDATE)
        GROUP BY TRUNC(rt.THOIGIAN_RUT_TIEN)
    )
    GROUP BY ngay
    ORDER BY ngay;
END;
/

-- Procedure xem chi tiết đặt phòng
CREATE OR REPLACE PROCEDURE XemChiTietDatPhong (
    p_chi_tiet_id       IN  NUMBER,
    p_detail_cursor     OUT SYS_REFCURSOR
)
IS
    v_chi_tiet_exists   NUMBER;
    ChiTietNotFound     EXCEPTION;
BEGIN
    -- Kiểm tra chi tiết đặt phòng có tồn tại không
    SELECT COUNT(*)
    INTO v_chi_tiet_exists
    FROM CHI_TIET_DAT_PHONG
    WHERE ID = p_chi_tiet_id;

    IF v_chi_tiet_exists = 0 THEN
        RAISE ChiTietNotFound;
    END IF;

    -- Cursor trả về thông tin chi tiết đặt phòng
    OPEN p_detail_cursor FOR
        SELECT
            -- Thông tin chi tiết đặt phòng
            ctdp.ID as chi_tiet_id,
            dp.ID as dat_phong_id,
            ctdp.SO_LUONG_PHONG,
            ctdp.SO_LUONG_DICH_VU_YEU_CAU,
            ctdp.TONG_GIATIEN,
            TO_CHAR(ctdp.NGAY_BAT_DAU, 'DD/MM/YYYY HH24:MI') as ngay_bat_dau,
            TO_CHAR(ctdp.NGAY_KET_THUC, 'DD/MM/YYYY HH24:MI') as ngay_ket_thuc,
            TO_CHAR(dp.THOI_GIAN_TAO, 'DD/MM/YYYY HH24:MI') as thoi_gian_dat,
            ctdp.TRANG_THAI as trang_thai_chi_tiet,
            dp.TRANG_THAI as trang_thai_dat_phong,

            -- Thông tin resort
            knd.ID as resort_id,
            knd.TEN as ten_resort,
            knd.DIA_CHI as dia_chi_resort,

            -- Thông tin loại phòng
            lp.ID as loai_phong_id,
            lp.TEN_LOAI_PHONG,
            lp.DIEN_TICH,
            lp.SO_GIUONG,
            lp.SO_NGUOI,

            -- Thông tin khách hàng
            u.HO_TEN as ho_ten,
            u.SDT as sdt,
            u.EMAIL as email,
            kh.DIA_CHI as dia_chi_khach_hang,

            -- Thông tin thanh toán
            dp.TAIKHOAN_NGANHANG,
            dp.TEN_TKNH,
            dp.TEN_NGANHANG,

            -- Tính trạng thái hiển thị
            CASE
                WHEN ctdp.TRANG_THAI = 'Đã hủy' THEN 'Đã hủy'
                WHEN ctdp.NGAY_KET_THUC < SYSDATE THEN 'Đã hoàn thành'
                WHEN ctdp.NGAY_BAT_DAU > SYSDATE THEN 'Sắp tới'
                ELSE 'ongoing'
            END as tinh_trang

        FROM CHI_TIET_DAT_PHONG ctdp
        JOIN DAT_PHONG dp ON ctdp.ID_DAT_PHONG = dp.ID
        JOIN GOI_DAT_PHONG gdp ON ctdp.ID_GOI_DAT_PHONG = gdp.ID
        JOIN LOAI_PHONG lp ON gdp.ID_LOAI_PHONG = lp.ID
        JOIN KHU_NGHI_DUONG knd ON lp.ID_KHU_NGHI_DUONG = knd.ID
        JOIN KHACH_HANG kh ON dp.ID_KHACH_HANG = kh.ID
        JOIN TAI_KHOAN tk ON kh.ID_TAI_KHOAN = tk.ACCOUNT_ID
        JOIN NGUOI_DUNG u ON tk.USER_ID = u.USER_ID
        WHERE ctdp.ID = p_chi_tiet_id;

EXCEPTION
    WHEN ChiTietNotFound THEN
        RAISE_APPLICATION_ERROR(-20001, 'Không tìm thấy thông tin đặt phòng');
    WHEN OTHERS THEN
        -- Đóng cursor nếu có lỗi
        IF p_detail_cursor%ISOPEN THEN
            CLOSE p_detail_cursor;
        END IF;

        RAISE_APPLICATION_ERROR(-20999, 'Lỗi hệ thống khi xem chi tiết đặt phòng');
END;
/


-- Procedure Xóa một đặt phòng và các chi tiết đặt phòng liên quan
CREATE OR REPLACE PROCEDURE XoaDatPhong(
    p_dat_phong_id IN NUMBER
)
IS
    v_dat_phong_exists  NUMBER;
    v_chi_tiet_count    NUMBER;
    DatPhongNotFound    EXCEPTION;
BEGIN
    -- Kiểm tra đặt phòng có tồn tại và có trạng thái Pending không
    SELECT COUNT(*)
    INTO v_dat_phong_exists
    FROM DAT_PHONG
    WHERE ID = p_dat_phong_id
    AND TRANG_THAI = 'Pending';

    IF v_dat_phong_exists = 0 THEN
        RAISE DatPhongNotFound;
    END IF;

    -- Đếm số chi tiết đặt phòng sẽ bị xóa
    SELECT COUNT(*)
    INTO v_chi_tiet_count
    FROM CHI_TIET_DAT_PHONG
    WHERE ID_DAT_PHONG = p_dat_phong_id;

    -- Xóa chi tiết đặt phòng trước
    DELETE FROM CHI_TIET_DAT_PHONG
    WHERE ID_DAT_PHONG = p_dat_phong_id;

    -- Xóa đặt phòng
    DELETE FROM DAT_PHONG
    WHERE ID = p_dat_phong_id;

    COMMIT;

    DBMS_OUTPUT.PUT_LINE('Đã xóa thành công đặt phòng ID: ' || p_dat_phong_id);
    DBMS_OUTPUT.PUT_LINE('Số chi tiết đặt phòng đã xóa: ' || v_chi_tiet_count);

EXCEPTION
    WHEN DatPhongNotFound THEN
        RAISE_APPLICATION_ERROR(-20010, 'Đặt phòng không tồn tại hoặc đã thanh toán');
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20999, 'Lỗi hệ thống khi xóa đặt phòng');
END;
/

-- Procedure thêm chi tiết đặt phòng vào giỏ hàng
CREATE OR REPLACE PROCEDURE ThemChiTietVaoGioHang (
    p_khach_hang_id         IN  NUMBER,
    p_goi_dat_phong_id      IN  NUMBER,
    p_so_luong_phong        IN  NUMBER,
    p_so_luong_dich_vu      IN  NUMBER,
    p_ngay_bat_dau          IN  TIMESTAMP,
    p_ngay_ket_thuc         IN  TIMESTAMP,
    p_tong_gia_tien         IN  NUMBER,
    p_chi_tiet_id           OUT NUMBER
)
IS
    v_dat_phong_id          NUMBER;
    v_count                 NUMBER;
    v_khach_hang_exists     NUMBER;
    v_goi_dat_phong_exists  NUMBER;
    KhachHangNotFound       EXCEPTION;
    GoiDatPhongNotFound     EXCEPTION;
BEGIN
    -- Kiểm tra khách hàng có tồn tại không
    SELECT COUNT(*)
    INTO v_khach_hang_exists
    FROM KHACH_HANG
    WHERE ID = p_khach_hang_id;

    IF v_khach_hang_exists = 0 THEN
        RAISE KhachHangNotFound;
        RETURN;
    END IF;

    -- Kiểm tra gói đặt phòng có tồn tại không
    SELECT COUNT(*)
    INTO v_goi_dat_phong_exists
    FROM GOI_DAT_PHONG
    WHERE ID = p_goi_dat_phong_id;

    IF v_goi_dat_phong_exists = 0 THEN
        RAISE GoiDatPhongNotFound;
        RETURN;
    END IF;

    -- Kiểm tra xem khách hàng đã có giỏ hàng (DAT_PHONG) với trạng thái Pending chưa
    SELECT COUNT(*)
    INTO v_count
    FROM DAT_PHONG
    WHERE ID_KHACH_HANG = p_khach_hang_id
    AND TRANG_THAI = 'Pending';

    IF v_count = 0 THEN
        -- Chưa có giỏ hàng, tạo mới
            ID_KHACH_HANG,
            THOI_GIAN_TAO,
            TRANG_THAI,
            TONG_GIATIEN
        ) VALUES (
            p_khach_hang_id,
            SYSTIMESTAMP,
            'Pending',
            0
        ) RETURNING ID INTO v_dat_phong_id;

    ELSE
        -- Đã có giỏ hàng, lấy ID
        SELECT ID
        INTO v_dat_phong_id
        FROM DAT_PHONG
        WHERE ID_KHACH_HANG = p_khach_hang_id
        AND TRANG_THAI = 'Pending';
    END IF;

    -- Thêm chi tiết đặt phòng vào giỏ hàng
        ID_DAT_PHONG,
        ID_GOI_DAT_PHONG,
        SO_LUONG_PHONG,
        SO_LUONG_DICH_VU_YEU_CAU,
        TONG_GIATIEN,
        NGAY_BAT_DAU,
        NGAY_KET_THUC,
        TRANG_THAI
    ) VALUES (
        v_dat_phong_id,
        p_goi_dat_phong_id,
        p_so_luong_phong,
        p_so_luong_dich_vu,
        p_tong_gia_tien,
        p_ngay_bat_dau,
        p_ngay_ket_thuc,
        'Pending'
    ) RETURNING ID INTO p_chi_tiet_id;

    -- Cập nhật tổng giá tiền của đặt phòng
    UPDATE DAT_PHONG
    SET TONG_GIATIEN = (
        SELECT NVL(SUM(TONG_GIATIEN), 0)
        FROM CHI_TIET_DAT_PHONG
        WHERE ID_DAT_PHONG = v_dat_phong_id
    )
    WHERE ID = v_dat_phong_id;

    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Thêm vào giỏ hàng thành công');

EXCEPTION
    WHEN KhachHangNotFound THEN
        RAISE_APPLICATION_ERROR(-20001, 'Khách hàng không tồn tại');
    WHEN GoiDatPhongNotFound THEN
        RAISE_APPLICATION_ERROR(-20002, 'Gói đặt phòng không tồn tại');
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE_APPLICATION_ERROR(-20003,'Thêm vào giỏ hàng thất bại');
        p_chi_tiet_id := NULL;
END;
/

CREATE OR REPLACE PROCEDURE CAP_NHAT_SO_LUONG_PHONG (
  p_id_chi_tiet     IN NUMBER,
  p_so_luong_phong  IN NUMBER
)
AS
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM CHI_TIET_DAT_PHONG
  WHERE ID = p_id_chi_tiet;

  IF v_count = 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'Chi tiết đặt phòng không tồn tại.');
  END IF;

  UPDATE CHI_TIET_DAT_PHONG
  SET SO_LUONG_PHONG = p_so_luong_phong
  WHERE ID = p_id_chi_tiet;

  COMMIT;
END;
/

-- Procedure xem lịch sử đặt phòng với phân loại trạng thái
CREATE OR REPLACE PROCEDURE XemLichSuDatPhong (
    p_khach_hang_id     IN  NUMBER,
    p_completed_cursor  OUT SYS_REFCURSOR,        -- Đã hoàn thành
    p_cancelled_cursor  OUT SYS_REFCURSOR,        -- Đã hủy
    p_upcoming_cursor   OUT SYS_REFCURSOR         -- Sắp tới
)
IS
    v_khach_hang_exists NUMBER;
BEGIN
    -- Kiểm tra khách hàng có tồn tại không
    SELECT COUNT(*)
    INTO v_khach_hang_exists
    FROM KHACH_HANG
    WHERE ID = p_khach_hang_id;

    IF v_khach_hang_exists = 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'Khách hàng không tồn tại');
    END IF;

    -- Cursor cho các đặt phòng đã hoàn thành (completed)
    OPEN p_completed_cursor FOR
        SELECT
            ctdp.ID as chi_tiet_id,
            dp.ID as dat_phong_id,
            knd.TEN as ten_resort,
            lp.TEN_LOAI_PHONG as ten_loai_phong,
            ctdp.SO_LUONG_PHONG,
            ctdp.TONG_GIATIEN,
            TO_CHAR(ctdp.NGAY_BAT_DAU, 'DD/MM/YYYY HH24:MI') as ngay_bat_dau,
            TO_CHAR(ctdp.NGAY_KET_THUC, 'DD/MM/YYYY HH24:MI') as ngay_ket_thuc,
            TO_CHAR(dp.THOI_GIAN_TAO, 'DD/MM/YYYY HH24:MI') as thoi_gian_dat,
            'completed' as trang_thai_hien_thi
        FROM CHI_TIET_DAT_PHONG ctdp
        JOIN DAT_PHONG dp ON ctdp.ID_DAT_PHONG = dp.ID
        JOIN GOI_DAT_PHONG gdp ON ctdp.ID_GOI_DAT_PHONG = gdp.ID
        JOIN LOAI_PHONG lp ON gdp.ID_LOAI_PHONG = lp.ID
        JOIN KHU_NGHI_DUONG knd ON lp.ID_KHU_NGHI_DUONG = knd.ID
        WHERE dp.ID_KHACH_HANG = p_khach_hang_id
        AND dp.TRANG_THAI = 'Đã thanh toán'
        AND ctdp.TRANG_THAI != 'Đã hủy'
        AND ctdp.NGAY_KET_THUC < SYSDATE
        ORDER BY ctdp.NGAY_KET_THUC DESC;

    -- Cursor cho các đặt phòng đã hủy (cancelled)
    OPEN p_cancelled_cursor FOR
        SELECT
            ctdp.ID as chi_tiet_id,
            dp.ID as dat_phong_id,
            knd.TEN as ten_resort,
            lp.TEN_LOAI_PHONG as ten_loai_phong,
            ctdp.SO_LUONG_PHONG,
            ctdp.TONG_GIATIEN,
            TO_CHAR(ctdp.NGAY_BAT_DAU, 'DD/MM/YYYY HH24:MI') as ngay_bat_dau,
            TO_CHAR(ctdp.NGAY_KET_THUC, 'DD/MM/YYYY HH24:MI') as ngay_ket_thuc,
            TO_CHAR(dp.THOI_GIAN_TAO, 'DD/MM/YYYY HH24:MI') as thoi_gian_dat,
            'cancelled' as trang_thai_hien_thi
        FROM CHI_TIET_DAT_PHONG ctdp
        JOIN DAT_PHONG dp ON ctdp.ID_DAT_PHONG = dp.ID
        JOIN GOI_DAT_PHONG gdp ON ctdp.ID_GOI_DAT_PHONG = gdp.ID
        JOIN LOAI_PHONG lp ON gdp.ID_LOAI_PHONG = lp.ID
        JOIN KHU_NGHI_DUONG knd ON lp.ID_KHU_NGHI_DUONG = knd.ID
        WHERE dp.ID_KHACH_HANG = p_khach_hang_id
        AND dp.TRANG_THAI = 'Đã thanh toán'
        AND ctdp.TRANG_THAI = 'Đã hủy'
        ORDER BY dp.THOI_GIAN_TAO DESC;

    -- Cursor cho các đặt phòng sắp tới (upcoming)
    OPEN p_upcoming_cursor FOR
        SELECT
            ctdp.ID as chi_tiet_id,
            dp.ID as dat_phong_id,
            knd.TEN as ten_resort,
            lp.TEN_LOAI_PHONG as ten_loai_phong,
            ctdp.SO_LUONG_PHONG,
            ctdp.TONG_GIATIEN,
            TO_CHAR(ctdp.NGAY_BAT_DAU, 'DD/MM/YYYY HH24:MI') as ngay_bat_dau,
            TO_CHAR(ctdp.NGAY_KET_THUC, 'DD/MM/YYYY HH24:MI') as ngay_ket_thuc,
            TO_CHAR(dp.THOI_GIAN_TAO, 'DD/MM/YYYY HH24:MI') as thoi_gian_dat,
            'upcoming' as trang_thai_hien_thi
        FROM CHI_TIET_DAT_PHONG ctdp
        JOIN DAT_PHONG dp ON ctdp.ID_DAT_PHONG = dp.ID
        JOIN GOI_DAT_PHONG gdp ON ctdp.ID_GOI_DAT_PHONG = gdp.ID
        JOIN LOAI_PHONG lp ON gdp.ID_LOAI_PHONG = lp.ID
        JOIN KHU_NGHI_DUONG knd ON lp.ID_KHU_NGHI_DUONG = knd.ID
        WHERE dp.ID_KHACH_HANG = p_khach_hang_id
        AND dp.TRANG_THAI = 'Đã thanh toán'
        AND ctdp.TRANG_THAI != 'Đã hủy'
        AND ctdp.NGAY_BAT_DAU > SYSDATE
        ORDER BY ctdp.NGAY_BAT_DAU ASC;

EXCEPTION
    WHEN OTHERS THEN
        -- Đóng các cursor nếu có lỗi
        IF p_completed_cursor%ISOPEN THEN
            CLOSE p_completed_cursor;
        END IF;
        IF p_cancelled_cursor%ISOPEN THEN
            CLOSE p_cancelled_cursor;
        END IF;
        IF p_upcoming_cursor%ISOPEN THEN
            CLOSE p_upcoming_cursor;
        END IF;

        RAISE_APPLICATION_ERROR(-20999, 'Lỗi hệ thống khi xem lịch sử đặt phòng: ' || SQLERRM);
END;
/
--Procedure tim loai phong
CREATE OR REPLACE PROCEDURE TimLoaiPhong (
    p_resortId IN NUMBER,
    p_ngay_nhan IN  TIMESTAMP,
    p_ngay_tra  IN  TIMESTAMP,
    p_so_nguoi  IN  NUMBER,
    p_output    OUT SYS_REFCURSOR
)
IS
BEGIN
  OPEN p_output FOR
    SELECT lp.ID,
           lp.ID_KHU_NGHI_DUONG,
           lp.TEN_LOAI_PHONG,
           lp.DIEN_TICH,
           lp.LOAI_PHONG_THEO_SO_LUONG,
           lp.LOAI_PHONG_THEO_TIEU_CHUAN,
           lp.SO_GIUONG,
           lp.SO_NGUOI,
           lp.GIA
    FROM LOAI_PHONG lp
    JOIN PHONG p ON p.ID_LOAI_PHONG = lp.ID
    WHERE lp.ID_KHU_NGHI_DUONG = p_resortId
    AND p.TRANG_THAI = 'Available'
    AND NOT EXISTS (
           SELECT 1
           FROM   thoigian_phong_ban tpb
           WHERE  tpb.id_phong = p.id
             AND  tpb.ngay_bat_dau < p_ngay_tra
             AND  tpb.ngay_ket_thuc > p_ngay_nhan);
END;
/

-- Procedure lấy top 6 khu nghỉ dưỡng có lượt đánh giá cao nhất
CREATE OR REPLACE PROCEDURE Top6ResortDanhGiaCaoNhat (
    p_output OUT SYS_REFCURSOR
)
IS
BEGIN
    OPEN p_output FOR
        WITH ResortInfo AS (
            SELECT
                knd.ID AS resort_id,
                knd.TEN AS ten_resort,
                knd.DANH_GIA AS danh_gia,
                p_tp.TEN_THANH_PHO AS thanh_pho,
                COUNT(DISTINCT dg.ID) AS so_luong_danh_gia,
                MIN(lp.GIA) AS gia_thap_nhat
            FROM KHU_NGHI_DUONG knd
            JOIN PHUONG p_ph ON knd.PHUONG_ID = p_ph.ID
            JOIN QUAN p_quan ON p_ph.ID_QUAN = p_quan.ID
            JOIN THANH_PHO p_tp ON p_quan.ID_THANH_PHO = p_tp.ID
            LEFT JOIN DANH_GIA dg ON dg.ID_KHU_NGHI_DUONG = knd.ID
            JOIN LOAI_PHONG lp ON lp.ID_KHU_NGHI_DUONG = knd.ID
            GROUP BY knd.ID, knd.TEN, knd.DANH_GIA, p_tp.TEN_THANH_PHO
            ORDER BY so_luong_danh_gia DESC, gia_thap_nhat ASC
            FETCH FIRST 6 ROWS ONLY
        ),
        PhongCount AS (
            SELECT
                lp.ID_KHU_NGHI_DUONG AS resort_id,
                COUNT(p.ID) AS so_phong
            FROM LOAI_PHONG lp
            JOIN PHONG p ON p.ID_LOAI_PHONG = lp.ID
            WHERE lp.ID_KHU_NGHI_DUONG IN (SELECT resort_id FROM ResortInfo)
            GROUP BY lp.ID_KHU_NGHI_DUONG
        ),
        FirstImage AS (
            SELECT
                h.ID_KHU_NGHI_DUONG AS resort_id,
                h.URL AS hinh_anh
            FROM (
                SELECT
                    h.*,
                    ROW_NUMBER() OVER (PARTITION BY h.ID_KHU_NGHI_DUONG ORDER BY h.ID) AS rn
                FROM HINH_KHU_NGHI_DUONG h
                WHERE h.ID_KHU_NGHI_DUONG IN (SELECT resort_id FROM ResortInfo)
            ) h
            WHERE h.rn = 1
        )
        SELECT
            ri.ten_resort,
            ri.thanh_pho,
            pc.so_phong,
            ri.gia_thap_nhat,
            ri.so_luong_danh_gia,
            fi.hinh_anh,
            ri.danh_gia
        FROM ResortInfo ri
        JOIN PhongCount pc ON ri.resort_id = pc.resort_id
        LEFT JOIN FirstImage fi ON ri.resort_id = fi.resort_id
        ORDER BY ri.so_luong_danh_gia DESC, ri.gia_thap_nhat ASC;
END;
/
CREATE OR REPLACE PROCEDURE SP_ALLOCATE_ROOMS_FOR_BOOKING(
    P_DAT_PHONG_ID IN NUMBER,
    P_RESULT OUT VARCHAR2
) IS
    V_PHONG_ID       NUMBER;
    V_COUNT          NUMBER := 0;
    V_CURRENT_STATUS VARCHAR2(50);
BEGIN
 
    -- Initialize result
    P_RESULT := 'SUCCESS';
 
    -- Get current booking status
    BEGIN
        SELECT
            TRANG_THAI INTO V_CURRENT_STATUS
        FROM
            DAT_PHONG
        WHERE
            ID = P_DAT_PHONG_ID;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            P_RESULT := 'ERROR: Booking not found';
            RETURN;
    END;

    -- Check if room allocation is needed
    IF V_CURRENT_STATUS = 'Đã thanh toán' THEN
        DBMS_OUTPUT.PUT_LINE('Allocating rooms...');
 
        -- Phân bổ phòng cho từng chi tiết đặt phòng
        FOR CHI_TIET_REC IN (
            SELECT
                CTDP.ID            AS CHI_TIET_ID,
                CTDP.NGAY_BAT_DAU  AS NGAY_BAT_DAU,
                CTDP.NGAY_KET_THUC AS NGAY_KET_THUC,
                LP.ID              AS LOAI_PHONG_ID,
                KND.ID             AS KHU_NGHI_DUONG_ID,
                HD.ID              AS HOA_DON_ID
            FROM
                CHI_TIET_DAT_PHONG CTDP
                JOIN GOI_DAT_PHONG GDP
                ON CTDP.ID_GOI_DAT_PHONG = GDP.ID
                JOIN LOAI_PHONG LP
                ON GDP.ID_LOAI_PHONG = LP.ID
                JOIN KHU_NGHI_DUONG KND
                ON LP.ID_KHU_NGHI_DUONG = KND.ID
                JOIN HOA_DON HD
                ON HD.ID_CHI_TIET_DAT_PHONG = CTDP.ID
            WHERE
                CTDP.ID_DAT_PHONG = P_DAT_PHONG_ID
        ) LOOP
            V_COUNT := V_COUNT + 1;
 
            -- Tìm phòng trống phù hợp
            BEGIN
                SELECT
                    P.ID INTO V_PHONG_ID
                FROM
                    PHONG              P
                WHERE
                    P.ID_LOAI_PHONG = CHI_TIET_REC.LOAI_PHONG_ID
                    AND P.ID_KHU_NGHI_DUONG = CHI_TIET_REC.KHU_NGHI_DUONG_ID
                    AND P.TRANG_THAI = 'Available'
                    AND NOT EXISTS (
                        SELECT
                            1
                        FROM
                            THOIGIAN_PHONG_BAN TPB
                        WHERE
                            TPB.ID_PHONG = P.ID
                            AND TPB.NGAY_BAT_DAU <= CHI_TIET_REC.NGAY_KET_THUC
                            AND TPB.NGAY_KET_THUC >= CHI_TIET_REC.NGAY_BAT_DAU
                    )
                    AND ROWNUM = 1;
 
                -- Thêm vào bảng THOIGIAN_PHONG_BAN
                    ID_PHONG,
                    NGAY_BAT_DAU,
                    NGAY_KET_THUC,
                    ID_HOA_DON
                ) VALUES (
                    V_PHONG_ID,
                    CHI_TIET_REC.NGAY_BAT_DAU,
                    CHI_TIET_REC.NGAY_KET_THUC,
                    CHI_TIET_REC.HOA_DON_ID
                );
                DBMS_OUTPUT.PUT_LINE('Đã thêm phòng '
                                     || V_PHONG_ID
                                     || ' vào THOIGIAN_PHONG_BAN');
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    DBMS_OUTPUT.PUT_LINE('Không tìm thấy phòng trống cho loại phòng: '
                                         || CHI_TIET_REC.LOAI_PHONG_ID);
                    P_RESULT := 'Không có đủ phòng cho loại phòng'
                                || CHI_TIET_REC.LOAI_PHONG_ID;
                WHEN OTHERS THEN
                    DBMS_OUTPUT.PUT_LINE('Lỗi khi thêm vào THOIGIAN_PHONG_BAN: '
                                         || SQLERRM);
                    P_RESULT := 'ERROR: '
                                || SQLERRM;
                    RAISE;
            END;
        END LOOP;

        DBMS_OUTPUT.PUT_LINE('Đã phân bổ phòng cho '
                             || V_COUNT
                             || ' booking details');
        COMMIT;
    ELSE
        DBMS_OUTPUT.PUT_LINE('Trạng thái đặt phòng "Đã thanh toán" - không thể thanh toán');
        P_RESULT := 'Trạng thái đặt phòng "Đã thanh toán" '
                    || V_CURRENT_STATUS
                    || ' - không thể thanh toán';
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        P_RESULT := 'ERROR: '
                    || SQLERRM;
        DBMS_OUTPUT.PUT_LINE('Error in SP_ALLOCATE_ROOMS_FOR_BOOKING: '
                             || SQLERRM);
        RAISE;
END SP_ALLOCATE_ROOMS_FOR_BOOKING;
/


CREATE OR REPLACE TRIGGER TRG_DAT_PHONG
AFTER UPDATE ON DAT_PHONG
FOR EACH ROW
BEGIN
    IF :OLD.TRANG_THAI != :NEW.TRANG_THAI THEN
        UPDATE CHI_TIET_DAT_PHONG
        SET
            TRANG_THAI = :NEW.TRANG_THAI
        WHERE
            ID_DAT_PHONG = :NEW.ID;
    END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_LOAI_PHONG 
AFTER UPDATE ON LOAI_PHONG FOR EACH ROW
BEGIN
    IF :OLD.GIA != :NEW.GIA THEN

        UPDATE GOI_DAT_PHONG GDP
        SET
            TONG_GIATIEN = TONG_GIATIEN + (
                :NEW.GIA - :OLD.GIA
            )
        WHERE
            GDP.ID_LOAI_PHONG = :NEW.ID;
    END IF;
END;
/
CREATE OR REPLACE TRIGGER TRG_DICH_VU_KHU_NGHI_DUONG 
AFTER UPDATE ON DICH_VU_KHU_NGHI_DUONG FOR EACH ROW
BEGIN
    IF :OLD.GIA != :NEW.GIA THEN
        UPDATE GOI_DAT_PHONG
        SET
            TONG_GIATIEN = TONG_GIATIEN + (
                :NEW.GIA - :OLD.GIA
            )
        WHERE
            ID IN (
                SELECT
                    ID_GOI_DAT_PHONG
                FROM
                    DICH_VU_MAC_DINH
                WHERE
                    ID_DICH_VU_KHU_NGHI_DUONG = :NEW.ID
            );
    END IF;


    IF :OLD.IS_DELETED != :NEW.IS_DELETED THEN
        IF :NEW.IS_DELETED = 1 THEN
            UPDATE GOI_DAT_PHONG
            SET
                TONG_GIATIEN = TONG_GIATIEN - :NEW.GIA
            WHERE
                ID IN (
                    SELECT
                        ID_DICH_VU_KHU_NGHI_DUONG
                    FROM
                        DICH_VU_MAC_DINH
                    WHERE
                        ID_DICH_VU_KHU_NGHI_DUONG = :NEW.ID
                );
        ELSIF :NEW.IS_DELETED = 0 THEN
            UPDATE GOI_DAT_PHONG
            SET
                TONG_GIATIEN = TONG_GIATIEN + :NEW.GIA
            WHERE
                ID IN (
                    SELECT
                        ID_DICH_VU_KHU_NGHI_DUONG
                    FROM
                        DICH_VU_MAC_DINH
                    WHERE
                        ID_DICH_VU_KHU_NGHI_DUONG = :NEW.ID
                );
        END IF;
    END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_GOI_DAT_PHONG 
AFTER UPDATE OR DELETE ON GOI_DAT_PHONG FOR EACH ROW 
BEGIN 
            IF UPDATING THEN 
                       IF :OLD.TONG_GIATIEN != :NEW.TONG_GIATIEN THEN
                                    UPDATE CHI_TIET_DAT_PHONG CTDP
                                    SET CTDP.TONG_GIATIEN = CTDP.TONG_GIATIEN + ( :NEW.TONG_GIATIEN - :OLD.TONG_GIATIEN )
                                    WHERE CTDP.ID_GOI_DAT_PHONG = :NEW.ID;
                       END IF;
            END IF;
            
            IF DELETING THEN
                       UPDATE CHI_TIET_DAT_PHONG CTDP
                       SET CTDP.TONG_GIATIEN = CTDP.TONG_GIATIEN - :OLD.TONG_GIATIEN
                       WHERE CTDP.ID_GOI_DAT_PHONG = :NEW.ID;
            END IF;
END;
/


CREATE OR REPLACE TRIGGER TRG_TINH_TONG_GIATIEN_CHI_TIET_DP BEFORE INSERT OR UPDATE ON CHI_TIET_DAT_PHONG FOR EACH ROW DECLARE V_GIATRI NUMBER := 0;
V_LOAIGIAMGIA NVARCHAR2(510);
V_GIAGOC NUMBER;
V_MUCTOIDA NUMBER;
BEGIN
    SELECT
        TONG_GIATIEN INTO V_GIAGOC
    FROM
        GOI_DAT_PHONG
    WHERE
        ID = :NEW.ID_GOI_DAT_PHONG;


    IF UPDATING AND :NEW.ID_GIAMGIA IS NOT NULL THEN
        SELECT
            LOAI_GIAMGIA,
            GIA_TRI,
            MUC_TOI_DA INTO V_LOAIGIAMGIA,
            V_GIATRI,
            V_MUCTOIDA
        FROM
            GIAMGIA
        WHERE
            ID = :NEW.ID_GIAMGIA;
        IF V_LOAIGIAMGIA = 'PERCENT' THEN
            :NEW.TONG_GIATIEN := V_GIAGOC * (1 - V_GIATRI / 100);
            IF :NEW.TONG_GIATIEN >= V_MUCTOIDA THEN
                :NEW.TONG_GIATIEN := V_MUCTOIDA;
            END IF;
        ELSIF V_LOAIGIAMGIA = 'AMOUNT' THEN
            :NEW.TONG_GIATIEN := V_GIAGOC - V_GIATRI;
        END IF;
    ELSE
        :NEW.TONG_GIATIEN := V_GIAGOC;
    END IF;
END;

CREATE OR REPLACE TRIGGER TRG_UPDATE_DIEM_TRUNG_BINH
AFTER INSERT ON DANH_GIA
FOR EACH ROW
DECLARE
  v_avg_diem NUMBER(3,1);
BEGIN
  SELECT ROUND(AVG(DIEM), 1)
  INTO v_avg_diem
  FROM DANH_GIA
  WHERE ID_KHU_NGHI_DUONG = :NEW.ID_KHU_NGHI_DUONG;
  UPDATE KHU_NGHI_DUONG
  SET DANH_GIA = v_avg_diem
  WHERE ID = :NEW.ID_KHU_NGHI_DUONG;
END;
/


CREATE OR REPLACE TRIGGER TRG_CHECK_SO_DU_BEFORE_RUTTIEN
BEFORE INSERT ON LICH_SU_RUT_TIEN
FOR EACH ROW
DECLARE
  v_sodu_hientai DOI_TAC.SO_DU%TYPE;
BEGIN
  SELECT SO_DU
  INTO v_sodu_hientai
  FROM DOI_TAC
  WHERE ID = :NEW.ID_DOI_TAC
  FOR UPDATE;

  IF v_sodu_hientai - :NEW.SOTIEN < 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'Số dư không đủ để rút tiền!');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_UPDATE_DIEM_TICH_LUY
AFTER INSERT ON DANH_GIA
FOR EACH ROW
BEGIN
  UPDATE KHACH_HANG
  SET DIEM_TICH_LUY = DIEM_TICH_LUY + 10
  WHERE ID = :NEW.ID_KHACH_HANG;
END;
/

CREATE OR REPLACE TRIGGER TRG_UPDATE_DIEM_TICH_LUY_KHI_DOI_MA
AFTER INSERT ON KHO_MA_GIAM_GIA
FOR EACH ROW
DECLARE
  v_gia_tri NUMBER(12,2);
BEGIN
  -- Lấy số điểm cần trừ tương ứng mã giảm giá
  SELECT GIA_TRI INTO v_gia_tri
  FROM GIAMGIA
  WHERE ID = :NEW.ID_GIAMGIA;

  -- Trừ điểm tích lũy của khách hàng
  UPDATE KHACH_HANG
  SET DIEM_TICH_LUY = DIEM_TICH_LUY - v_gia_tri
  WHERE ID = :NEW.ID_KHACH_HANG;
END;
/

CREATE OR REPLACE TRIGGER TRG_UPDATE_SODU_DOITAC
AFTER UPDATE OF TINH_TRANG ON CHI_TIET_DAT_PHONG
FOR EACH ROW
DECLARE
  v_id_doi_tac NUMBER;
  v_tien_doi_tac NUMBER;
  v_sodu_hientai NUMBER;
BEGIN
  IF :NEW.TRANG_THAI = 'DA_HUY' AND :OLD.TRANG_THAI != 'DA_HUY' THEN
    -- Lấy ID_DOI_TAC từ HOA_DON dựa vào ID_CHI_TIET_DAT_PHONG
    SELECT hd.ID_DOI_TAC
    INTO v_id_doi_tac
    FROM HOA_DON hd
    WHERE hd.ID_CHI_TIET_DAT_PHONG = :NEW.ID;

    -- Tính số tiền đối tác được hưởng (80% tổng giá tiền)
    v_tien_doi_tac := ROUND(:NEW.TONG_GIATIEN * 0.8, 0);

    -- Lấy số dư hiện tại của đối tác
    SELECT SO_DU
    INTO v_sodu_hientai
    FROM DOI_TAC
    WHERE ID = v_id_doi_tac;

    -- Cập nhật số dư mới (trừ đi tiền đối tác)
    UPDATE DOI_TAC
    SET SO_DU = v_sodu_hientai - v_tien_doi_tac
    WHERE ID = v_id_doi_tac;
  END IF;
END;
/


-- Xử lý truy vấn đồng thời.

-- 3.4.1. Lost Update
CREATE OR REPLACE PROCEDURE RUT_TIEN (
  p_id_doi_tac IN NUMBER,
  p_so_tien IN NUMBER
) AS
  v_so_du DOI_TAC.SO_DU%TYPE;
BEGIN
  -- 1. Đọc số dư hiện tại
  SELECT SO_DU INTO v_so_du FROM DOI_TAC WHERE ID = p_id_doi_tac;

  -- 2. Kiểm tra số dư đủ rút không
  IF v_so_du < p_so_tien THEN
    RAISE_APPLICATION_ERROR(-20001, 'Số dư không đủ để rút tiền');
  END IF;

  -- 3. Cập nhật số dư mới
  UPDATE DOI_TAC
  SET SO_DU = v_so_du - p_so_tien
  WHERE ID = p_id_doi_tac;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR(-20002, 'Không tìm thấy đối tác');
  WHEN OTHERS THEN
    ROLLBACK;
    RAISE;
END;
/

CREATE OR REPLACE PROCEDURE CONG_TIEN (
  p_id_doi_tac IN NUMBER,
  p_so_tien IN NUMBER
) AS
  v_so_du DOI_TAC.SO_DU%TYPE;
BEGIN
  -- 1. Đọc số dư hiện tại
  SELECT SO_DU INTO v_so_du FROM DOI_TAC WHERE ID = p_id_doi_tac;

  -- 2. Cập nhật số dư mới
  UPDATE DOI_TAC
  SET SO_DU = v_so_du + p_so_tien
  WHERE ID = p_id_doi_tac;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR(-20002, 'Không tìm thấy đối tác');
  WHEN OTHERS THEN
    ROLLBACK;
    RAISE;
END;
/


