-- 3.4.3. Dirty Read

CREATE OR REPLACE PROCEDURE UpdateTrangThaiPhong(
    p_id_phong IN NUMBER,
    p_trang_thai IN VARCHAR2
) AS
    phong_count NUMBER;
BEGIN

        DECLARE phong_count INT;

        SELECT COUNT(*)
        INTO phong_count
        FROM PHONG
        WHERE ID = p_id_phong;
    
        IF phong_count > 0 THEN
               UPDATE PHONG
               SET TRANG_THAI = p_trang_thai
               WHERE ID = p_id_phong;
        ELSE
               SIGNAL SQLSTATE '45000'
               SET MESSAGE_TEXT = 'Phòng không tồn tại';
        END IF;
END;
/

