CREATE OR REPLACE PROCEDURE UpdateTrangThaiPhong (
      p_id_phong  IN VARCHAR2,
      p_trang_thai IN NUMBER
)
AS
      phong_count NUMBER;
BEGIN
         START TRANSACTION;

         SELECT COUNT(*) INTO phong_count
         FROM PHONG
         WHERE ID = p_id_phong;

         IF phong_count > 0 THEN
                UPDATE PHONG
                SET TRANG_THAI = p_trang_thai;
                WHERE ID = p_trang_thai;
                COMMIT;
        ELSE
                ROLLBACK
                SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Phòng không tồn tại';
       END IF;
END;
/


