-- 3.4.3 Phantom Read
CREATE OR REPLACE PROCEDURE TIM_PHONG_BAN_NHIEU_NHAT(p_id_loai_phong IN LOAI_PHONG.ID%TYPE) AS
BEGIN
        FOR rec IN (
                  SELECT TPB.ID_PHONG, COUNT(*) AS SO_LAN_BAN
                  FROM THOIGIAN_PHONG_BAN TPB
                  JOIN PHONG P ON TPB.ID_PHONG = P.ID
                  WHERE P.ID_LOAI_PHONG = p_id_loai_phong
                  GROUP BY TPB.ID_PHONG
                  HAVING COUNT(*) = (SELECT MAX(SO_LAN) FROM
                                                             (SELECT COUNT(*) AS SO_LAN
                                                              FROM THOIGIAN_PHONG_BAN TPB2
                                                              JOIN PHONG P2 ON TPB2.ID_PHONG = P2.ID
                                                              WHERE P2.ID_LOAI_PHONG = p_id_loai_phong
                                                               GROUP BY TPB2.ID_PHONG))
        ) LOOP
                  DBMS_OUTPUT.PUT_LINE('Phong ID: ' || rec.ID_PHONG || ', So lan ban: ' || rec.SO_LAN_BAN);
        END LOOP;
END;
/

